package nl.dutchnations.server;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Private durable game state. Never serialize this object into a public response. */
final class BattleshipGame
{
    static final class RuleFailure extends IllegalArgumentException
    { RuleFailure(String message) { super(message); } }
    static final int SIZE = 8;
    static final int[] LENGTHS = {5, 4, 3, 3, 2};
    String key;
    String binding;
    boolean started, ready, retired;
    List<String> teamNames = new ArrayList<>();
    List<String> messages = new ArrayList<>(java.util.Arrays.asList("", ""));
    long startsAt, endsAt;
    List<Map<String, Integer>> fleets = new ArrayList<>();
    Map<String, Integer> goals = new LinkedHashMap<>();
    List<List<Shot>> shots = new ArrayList<>();

    static final class Shot
    {
        String coordinate;
        long at;
        Shot(String coordinate, long at) { this.coordinate = coordinate; this.at = at; }
    }

    static BattleshipGame create(String key, long start, long end, Map<String, Integer> goals,
                                 List<List<String>> first, List<List<String>> second)
    {
        if (key == null || key.length() > 200 || end <= start || goals.isEmpty() || goals.size() > 500)
            throw new RuleFailure("Ongeldige eventperiode of dropselectie");
        goals.forEach((id, goal) -> {
            if (id == null || !id.matches("DROP-[0-9]+") || goal == null || goal < 1 || goal > 7)
                throw new RuleFailure("Ongeldig dropdoel");
        });
        BattleshipGame game = new BattleshipGame();
        game.key = key; game.startsAt = start; game.endsAt = end; game.goals.putAll(goals);
        game.fleets.add(fleet(first)); game.fleets.add(fleet(second));
        game.shots.add(new ArrayList<>()); game.shots.add(new ArrayList<>());
        return game;
    }

    static String coordinate(String raw)
    {
        String value = raw == null ? "" : raw.trim().toUpperCase(Locale.ROOT);
        if (!value.matches("[A-H][1-8]")) throw new RuleFailure("Kies een vak van A1 tot H8");
        return value;
    }

    static Map<String, Integer> fleet(List<List<String>> placements)
    {
        if (placements == null || placements.size() != LENGTHS.length)
            throw new RuleFailure("Plaats alle vijf boten");
        Map<String, Integer> cells = new HashMap<>();
        for (int ship = 0; ship < LENGTHS.length; ship++)
        {
            List<String> input = placements.get(ship);
            if (input == null || input.size() != 2) throw new RuleFailure("Een boot heeft een beginvak en richting nodig");
            String origin = coordinate(input.get(0));
            String direction = input.get(1) == null ? "" : input.get(1).trim();
            boolean horizontal = "Horizontaal".equalsIgnoreCase(direction);
            if (!horizontal && !"Verticaal".equalsIgnoreCase(direction)) throw new RuleFailure("Kies Horizontaal of Verticaal");
            int x = origin.charAt(0) - 'A', y = Integer.parseInt(origin.substring(1)) - 1;
            for (int n = 0; n < LENGTHS[ship]; n++)
            {
                int col = x + (horizontal ? n : 0), row = y + (horizontal ? 0 : n);
                if (col >= SIZE || row >= SIZE) throw new RuleFailure("Een boot valt buiten het bord");
                String cell = "" + (char) ('A' + col) + (row + 1);
                if (cells.putIfAbsent(cell, ship) != null) throw new RuleFailure("Boten mogen niet overlappen");
            }
        }
        return cells;
    }

    int earned(Set<String> completed)
    {
        if (completed == null || !goals.keySet().containsAll(completed)) throw new RuleFailure("Onbekend dropdoel");
        return completed.size(); // A set of stable goal IDs, not completion transitions or item quantity.
    }

    int available(int team, Set<String> completed)
    { checkTeam(team); return Math.max(0, earned(completed) - shots.get(team).size()); }

    String fire(int team, String raw, Set<String> completed, long now)
    { return fire(team, raw, completed, now, false); }

    private String fire(int team, String raw, Set<String> completed, long now, boolean sameBatch)
    {
        checkTeam(team);
        if (now < startsAt || now >= endsAt) throw new RuleFailure("Het event is niet actief");
        if (!sameBatch && winner() != 0) throw new RuleFailure("Het spel is afgelopen");
        String target = coordinate(raw);
        for (Shot shot : shots.get(team)) if (shot.coordinate.equals(target)) throw new RuleFailure("Op dit vak is al geschoten");
        if (available(team, completed) == 0) throw new RuleFailure("Geen schoten beschikbaar");
        shots.get(team).add(new Shot(target, now));
        return outcome(team, target);
    }

    void fireBatch(List<String> targets, List<Set<String>> completed, long now)
    {
        boolean finishedBefore = winner() != 0;
        for (int team = 0; team < 2; team++) if (targets.get(team) != null)
        {
            try
            {
                if (finishedBefore) throw new RuleFailure("Het spel is afgelopen");
                String target = coordinate(targets.get(team));
                fire(team, target, completed.get(team), now, true);
                messages.set(team, target + ": " + outcome(team, target));
            }
            catch (IllegalArgumentException | IllegalStateException rejected) { messages.set(team, rejected.getMessage()); }
        }
    }

    String outcome(int team, String cell)
    {
        checkTeam(team);
        Set<String> fired = fired(team);
        if (!fired.contains(cell)) return "";
        Map<String, Integer> enemy = fleets.get(1 - team);
        Integer ship = enemy.get(cell);
        if (ship == null) return "MIS";
        boolean sunk = enemy.entrySet().stream().filter(e -> e.getValue().equals(ship)).allMatch(e -> fired.contains(e.getKey()));
        return sunk ? "GEZONKEN" : "RAAK";
    }

    int winner()
    {
        int winner = 0;
        for (int team = 0; team < 2; team++)
            if (fired(team).containsAll(fleets.get(1 - team).keySet())) winner += team + 1;
        return winner; // 3 means both teams sank the last ship in the same poll batch.
    }

    List<List<String>> publicBoard(int team)
    {
        checkTeam(team);
        List<List<String>> rows = new ArrayList<>();
        for (int y = 1; y <= SIZE; y++)
        {
            List<String> row = new ArrayList<>();
            for (int x = 0; x < SIZE; x++) row.add(outcome(team, "" + (char) ('A' + x) + y));
            rows.add(row);
        }
        return rows;
    }

    private Set<String> fired(int team)
    {
        Set<String> result = new HashSet<>();
        for (Shot shot : shots.get(team)) result.add(shot.coordinate);
        return result;
    }

    private static void checkTeam(int team)
    { if (team != 0 && team != 1) throw new RuleFailure("Onbekend team"); }
}

package nl.dutchnations.server;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.Set;

interface BattleshipGateway
{
    List<List<List<Object>>> batchValues(String file, String... ranges) throws IOException;
    void write(String file, Map<String, List<List<?>>> data) throws IOException;
    BattleshipSheets.Access privateAccess(String file) throws IOException;
    void protect(String file, Set<String> first, Set<String> second) throws IOException;
    void privateLocked(String file, boolean locked) throws IOException;
    void sourceLocked(String file, boolean locked, boolean payment) throws IOException;
}

package nl.dutchnations.server;

import com.google.auth.oauth2.ServiceAccountCredentials;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.zip.GZIPInputStream;

/** Fixed Google API hosts only. No credentials or fleet data are logged. */
final class BattleshipSheets implements BattleshipGateway
{
    private static final Gson JSON = new Gson();
    private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).followRedirects(HttpClient.Redirect.NEVER).build();
    private final ServiceAccountCredentials credentials;

    BattleshipSheets(String key) throws IOException
    {
        if (key == null || key.length() > 50000) throw new IOException("Google-servertoegang ontbreekt");
        try
        {
            credentials = (ServiceAccountCredentials) ServiceAccountCredentials.fromStream(new ByteArrayInputStream(key.getBytes(StandardCharsets.UTF_8)))
                .createScoped(Arrays.asList("https://www.googleapis.com/auth/spreadsheets", "https://www.googleapis.com/auth/drive.metadata.readonly"));
        }
        catch (Exception failure) { throw new IOException("Google-servertoegang is ongeldig"); }
    }

    static String id(String value)
    {
        if (value == null || !value.matches("[A-Za-z0-9_-]{20,128}")) throw new IllegalArgumentException("Ongeldige Sheet-koppeling");
        return value;
    }

    String revision(String file) throws IOException
    {
        JsonObject result=request("GET","https://www.googleapis.com/drive/v3/files/"+id(file)+"?fields=version",null);
        String revision=string(result,"version");
        if(!revision.matches("[0-9]{1,30}"))throw new IOException("Ongeldige Google-bestandsversie");
        return revision;
    }

    List<List<Object>> values(String file, String range) throws IOException
    {
        JsonObject result = request("GET", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file) + "/values/" + encode(range)
            + "?valueRenderOption=UNFORMATTED_VALUE", null);
        List<List<Object>> rows = new ArrayList<>();
        JsonArray data = result.getAsJsonArray("values");
        if (data != null) for (JsonElement r : data)
        {
            List<Object> row = new ArrayList<>();
            for (JsonElement c : r.getAsJsonArray()) row.add(c.isJsonNull() ? "" : c.getAsJsonPrimitive().isBoolean() ? c.getAsBoolean()
                : c.getAsJsonPrimitive().isNumber() ? c.getAsDouble() : c.getAsString());
            rows.add(row);
        }
        return rows;
    }

    public List<List<List<Object>>> batchValues(String file, String... ranges) throws IOException
    {
        StringBuilder url = new StringBuilder("https://sheets.googleapis.com/v4/spreadsheets/").append(id(file)).append("/values:batchGet?valueRenderOption=UNFORMATTED_VALUE");
        for (String range : ranges) url.append("&ranges=").append(encode(range));
        JsonArray values = request("GET", url.toString(), null).getAsJsonArray("valueRanges");
        if (values == null || values.size() != ranges.length) throw new IOException("Onvolledig Google-antwoord");
        List<List<List<Object>>> out = new ArrayList<>();
        for (JsonElement value : values)
        {
            List<List<Object>> rows = new ArrayList<>();
            JsonArray grid = value.getAsJsonObject().getAsJsonArray("values");
            if (grid != null) for (JsonElement r : grid)
            {
                List<Object> row = new ArrayList<>();
                for (JsonElement c : r.getAsJsonArray()) row.add(c.isJsonNull() ? "" : c.getAsJsonPrimitive().isBoolean() ? c.getAsBoolean()
                    : c.getAsJsonPrimitive().isNumber() ? c.getAsDouble() : c.getAsString());
                rows.add(row);
            }
            out.add(rows);
        }
        return out;
    }

    public void write(String file, Map<String, List<List<?>>> data) throws IOException
    {
        List<Object> values = new ArrayList<>();
        data.forEach((range, rows) -> values.add(map("range", range, "values", rows)));
        request("POST", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file) + "/values:batchUpdate",
            map("valueInputOption", "RAW", "data", values));
    }

    static final class Access
    {
        final Set<String> owners = new HashSet<>(), readers = new HashSet<>(), writers = new HashSet<>();
    }

    public Access privateAccess(String file) throws IOException
    {
        Access access = new Access(); String page = "";
        for (int n = 0; n < 10; n++)
        {
            JsonObject result = request("GET", "https://www.googleapis.com/drive/v3/files/" + id(file)
                + "/permissions?pageSize=100&fields=" + encode("nextPageToken,permissions(type,emailAddress,role,deleted)")
                + (page.isEmpty() ? "" : "&pageToken=" + encode(page)), null);
            JsonArray permissions = result.getAsJsonArray("permissions");
            if (permissions == null) throw new IOException("Privérechten konden niet worden gecontroleerd");
            for (JsonElement p : permissions)
            {
                JsonObject permission = p.getAsJsonObject();
                if (permission.has("deleted") && permission.get("deleted").getAsBoolean()) continue;
                if (!"user".equals(string(permission, "type"))) throw new IOException("Een privévloot mag niet openbaar of met een groep/domein worden gedeeld");
                String email = string(permission, "emailAddress").toLowerCase(java.util.Locale.ROOT), role = string(permission, "role");
                if (email.isEmpty()) throw new IOException("Onbekende privétoegang");
                if (email.equals(credentials.getClientEmail().toLowerCase(java.util.Locale.ROOT))) continue;
                access.readers.add(email);
                if ("owner".equals(role)) access.owners.add(email);
                if ("owner".equals(role) || "writer".equals(role)) access.writers.add(email);
            }
            page = string(result, "nextPageToken");
            if (page.isEmpty()) return access;
        }
        throw new IOException("Te veel privétoegangsregels");
    }

    static void separated(Access first, Access second) throws IOException
    {
        Set<String> overlap = new HashSet<>(first.readers); overlap.retainAll(second.readers);
        Set<String> owners = new HashSet<>(first.owners); owners.retainAll(second.owners); overlap.removeAll(owners);
        if (!overlap.isEmpty()) throw new IOException("Een niet-eigenaar heeft toegang tot beide privévloten");
    }

    /** Freeze both input areas before reading a request, preventing edit/publish races. */
    public void protect(String file, Set<String> first, Set<String> second) throws IOException
    {
        JsonObject metadata = request("GET", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file)
            + "?fields=" + encode("properties(timeZone),sheets(properties(sheetId,title),protectedRanges(protectedRangeId,description,range))"), null);
        List<Object> updates = publicProtectionPlan(metadata, first, second, credentials.getClientEmail());
        request("POST", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file) + ":batchUpdate", map("requests", updates));
    }

    static List<Object> publicProtectionPlan(JsonObject metadata, Set<String> first, Set<String> second, String serviceEmail) throws IOException
    {
        if (!"Europe/Amsterdam".equals(string(metadata.getAsJsonObject("properties"), "timeZone")))
            throw new IOException("De eventsheet moet tijdzone Europe/Amsterdam gebruiken");
        List<Object> updates = new ArrayList<>();
        int board = sheet(metadata, "Tussenstand"), data = sheet(metadata, "Zeeslagdata");
        List<Object> free = Arrays.asList(range(board, 64, 65, 3, 5), range(board, 64, 65, 7, 8),
            range(board, 64, 65, 12, 14), range(board, 64, 65, 16, 17));
        protection(metadata, updates, board, "board", map("sheetId", board), Set.of(), free, serviceEmail);
        protection(metadata, updates, data, "public-data", map("sheetId", data), Set.of(), List.of(), serviceEmail);
        for (int team = 0; team < 2; team++)
        {
            int offset = team * 9; Set<String> editors = team == 0 ? first : second;
            protection(metadata, updates, board, "coordinate-" + team, range(board, 64, 65, 3 + offset, 5 + offset), editors, null, serviceEmail);
            protection(metadata, updates, board, "submit-" + team, range(board, 64, 65, 7 + offset, 8 + offset), editors, null, serviceEmail);
        }
        return updates;
    }

    public void privateLocked(String file, boolean locked) throws IOException
    {
        JsonObject metadata = request("GET", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file)
            + "?fields=" + encode("sheets(properties(sheetId,title),protectedRanges(protectedRangeId,description,range))"), null);
        int sheet = sheet(metadata, "Vloot");
        List<Object> updates = new ArrayList<>();
        if (locked) protection(metadata, updates, sheet, "private-fleet", map("sheetId", sheet), Set.of(), List.of());
        else for (JsonElement s : metadata.getAsJsonArray("sheets"))
        {
            JsonObject sh = s.getAsJsonObject();
            if (!sh.has("protectedRanges")) continue;
            for (JsonElement p : sh.getAsJsonArray("protectedRanges"))
                if ("DN_ZEESLAG_private-fleet".equals(string(p.getAsJsonObject(), "description")))
                    updates.add(map("deleteProtectedRange", map("protectedRangeId", p.getAsJsonObject().get("protectedRangeId").getAsInt())));
        }
        if (!updates.isEmpty()) request("POST", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file) + ":batchUpdate", map("requests", updates));
    }

    public void sourceLocked(String file, boolean locked, boolean payment) throws IOException
    {
        JsonObject metadata = request("GET", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file)
            + "?fields=" + encode("sheets(properties(sheetId,title,gridProperties(rowCount)),protectedRanges(protectedRangeId,description,range))"), null);
        List<Object> updates = new ArrayList<>();
        if (locked)
        {
            int settings = sheet(metadata, "Instellingen"), drops = sheet(metadata, "Drops"), max = 150;
            for (JsonElement s : metadata.getAsJsonArray("sheets"))
            {
                JsonObject p = s.getAsJsonObject().getAsJsonObject("properties");
                if (p.get("sheetId").getAsInt() == settings) max = p.getAsJsonObject("gridProperties").get("rowCount").getAsInt();
            }
            List<Object> free = payment ? Arrays.asList(range(settings,18,max,1,2),range(settings,18,max,5,6)) : List.of();
            protection(metadata,updates,settings,"source-settings",map("sheetId",settings),Set.of(),free);
            protection(metadata,updates,drops,"source-drops",map("sheetId",drops),Set.of(),List.of());
        }
        else for (JsonElement s : metadata.getAsJsonArray("sheets"))
        {
            JsonObject sh = s.getAsJsonObject(); if (!sh.has("protectedRanges")) continue;
            for (JsonElement p : sh.getAsJsonArray("protectedRanges"))
                if (Set.of("DN_ZEESLAG_source-settings","DN_ZEESLAG_source-drops").contains(string(p.getAsJsonObject(),"description")))
                    updates.add(map("deleteProtectedRange",map("protectedRangeId",p.getAsJsonObject().get("protectedRangeId").getAsInt())));
        }
        if (!updates.isEmpty()) request("POST", "https://sheets.googleapis.com/v4/spreadsheets/" + id(file) + ":batchUpdate", map("requests",updates));
    }

    private void protection(JsonObject metadata, List<Object> updates, int sheetId, String suffix, Object range,
                            Set<String> allowed, List<Object> free) throws IOException
    { protection(metadata, updates, sheetId, suffix, range, allowed, free, credentials.getClientEmail()); }

    private static void protection(JsonObject metadata, List<Object> updates, int sheetId, String suffix, Object range,
                            Set<String> allowed, List<Object> free, String serviceEmail) throws IOException
    {
        String tag = "DN_ZEESLAG_" + suffix;
        List<String> users = new ArrayList<>(allowed); users.add(serviceEmail);
        Map<String, Object> value = map("description", tag, "range", range, "warningOnly", false,
            "editors", map("users", users, "domainUsersCanEdit", false));
        if (free != null) value.put("unprotectedRanges", free);
        Integer found = null;
        for (JsonElement s : metadata.getAsJsonArray("sheets"))
        {
            JsonObject sh = s.getAsJsonObject();
            if (sh.getAsJsonObject("properties").get("sheetId").getAsInt() != sheetId || !sh.has("protectedRanges")) continue;
            for (JsonElement p : sh.getAsJsonArray("protectedRanges"))
            {
                JsonObject pr = p.getAsJsonObject();
                if (tag.equals(string(pr, "description"))) found = pr.get("protectedRangeId").getAsInt();
                else if (!pr.getAsJsonObject("range").has("startRowIndex") && !string(pr, "description").startsWith("DN_ZEESLAG_"))
                    throw new IOException("Bestaande bladbeveiliging wordt niet overschreven");
            }
        }
        if (found == null) updates.add(map("addProtectedRange", map("protectedRange", value)));
        else { value.put("protectedRangeId", found); updates.add(map("updateProtectedRange", map("protectedRange", value, "fields", "range,description,warningOnly,editors" + (free == null ? "" : ",unprotectedRanges")))); }
    }

    private static int sheet(JsonObject meta, String title) throws IOException
    {
        for (JsonElement s : meta.getAsJsonArray("sheets"))
        {
            JsonObject p = s.getAsJsonObject().getAsJsonObject("properties");
            if (title.equals(string(p, "title"))) return p.get("sheetId").getAsInt();
        }
        throw new IOException("Zeeslagtabblad ontbreekt");
    }

    JsonObject request(String method, String url, Object data) throws IOException
    { return request(method, url, data, 2_000_000); }

    JsonObject request(String method, String url, Object data, int limit) throws IOException
    { return request(method,url,data,limit,false); }

    JsonObject requestForView(String method,String url,Object data) throws IOException
    { return request(method,url,data,2_000_000,true); }

    static Duration requestTimeout(String method, boolean publicProjection)
    {
        // An initial public view can atomically publish thousands of styled cells.
        // Keep ordinary reads and private fleet operations on their short deadline.
        return Duration.ofSeconds(publicProjection && "POST".equals(method) ? 60 : 12);
    }

    private JsonObject request(String method,String url,Object data,int limit,boolean publicProjection) throws IOException
    {
        credentials.refreshIfExpired();
        HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(url)).timeout(requestTimeout(method,publicProjection))
            .header("Accept-Encoding", "gzip").header("User-Agent", "DutchNationsServer/1.0 (gzip)")
            .header("Authorization", "Bearer " + credentials.getAccessToken().getTokenValue());
        if (data == null) request.GET(); else request.header("Content-Type", "application/json").method(method, HttpRequest.BodyPublishers.ofString(JSON.toJson(data)));
        try
        {
            HttpResponse<java.io.InputStream> response = http.send(request.build(), HttpResponse.BodyHandlers.ofInputStream());
            try (java.io.InputStream body = response.body())
            {
                if (response.statusCode() != 200)
                {
                    String hint="";
                    // Only public projection writes may report a bounded schema error. Fleet operations remain opaque.
                    if(publicProjection)try {
                        JsonObject error=JsonParser.parseString(new String(responseBytes(body,response.headers().firstValue("Content-Encoding").orElse(""),4096),StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonObject("error");
                        String message=string(error,"message").replaceAll("[\\r\\n]"," ");
                        hint=": "+message.substring(0,Math.min(600,message.length()));
                    } catch(RuntimeException | IOException ignored) { }
                    throw new IOException("Google-koppeling: HTTP " + response.statusCode()+hint);
                }
                byte[] bytes = responseBytes(body,response.headers().firstValue("Content-Encoding").orElse(""),limit);
                return JsonParser.parseString(new String(bytes, StandardCharsets.UTF_8)).getAsJsonObject();
            }
        }
        catch (InterruptedException ex) { Thread.currentThread().interrupt(); throw new IOException("Google-controle onderbroken"); }
        catch (RuntimeException ex) { throw new IOException("Ongeldig Google-antwoord"); }
    }

    // The limit applies AFTER decompression too, so gzip cannot bypass the bound.
    static byte[] responseBytes(InputStream input,String encoding,int limit) throws IOException
    {
        if(limit<1)throw new IllegalArgumentException("Ongeldige antwoordlimiet");
        if(!encoding.isEmpty()&&!encoding.equalsIgnoreCase("identity")&&!encoding.equalsIgnoreCase("gzip"))throw new IOException("Onbekende Google-compressie");
        try(InputStream decoded=encoding.equalsIgnoreCase("gzip")?new GZIPInputStream(input):input)
        {
            byte[] bytes=decoded.readNBytes(limit+1);
            if(bytes.length>limit)throw new IOException("Google-antwoord is te groot");
            return bytes;
        }
    }

    static Map<String, Object> map(Object... pairs)
    { Map<String, Object> out = new LinkedHashMap<>(); for (int n = 0; n < pairs.length; n += 2) out.put((String) pairs[n], pairs[n + 1]); return out; }
    private static Map<String, Object> range(int sheet, int r1, int r2, int c1, int c2)
    { return map("sheetId", sheet, "startRowIndex", r1, "endRowIndex", r2, "startColumnIndex", c1, "endColumnIndex", c2); }
    private static String string(JsonObject object, String key) { return object.has(key) && !object.get(key).isJsonNull() ? object.get(key).getAsString() : ""; }
    private static String encode(String s) { return URLEncoder.encode(s, StandardCharsets.UTF_8); }
}

package nl.dutchnations.server;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Disabled until all three files and a Google service account are configured. */
final class BattleshipSync
{
    private final DutchNationsApi.Store store;
    private BattleshipGateway google;
    private String lastError = "";
    private String disabledControls = "";
    private final String main, first, second, credential;
    private final java.util.function.LongSupplier clock;

    BattleshipSync(DutchNationsApi.Store store)
    { this(store,null,System.getenv("DN_BATTLESHIP_PUBLIC_SHEET"),System.getenv("DN_BATTLESHIP_TEAM_ONE_SHEET"),System.getenv("DN_BATTLESHIP_TEAM_TWO_SHEET"),System.getenv("DN_GOOGLE_SERVICE_ACCOUNT_JSON"),System::currentTimeMillis); }
    BattleshipSync(DutchNationsApi.Store store, BattleshipGateway google, String main, String first, String second, String credential, java.util.function.LongSupplier clock)
    { this.store=store; this.google=google; this.main=main; this.first=first; this.second=second; this.credential=credential; this.clock=clock; }

    static boolean configured()
    {
        try
        {
            String one = BattleshipSheets.id(System.getenv("DN_BATTLESHIP_TEAM_ONE_SHEET"));
            String two = BattleshipSheets.id(System.getenv("DN_BATTLESHIP_TEAM_TWO_SHEET"));
            String main = BattleshipSheets.id(System.getenv("DN_BATTLESHIP_PUBLIC_SHEET"));
            String key = System.getenv("DN_GOOGLE_SERVICE_ACCOUNT_JSON");
            return !one.equals(two) && !main.equals(one) && !main.equals(two) && key != null && !key.trim().isEmpty() && key.length() <= 50000;
        }
        catch (IllegalArgumentException ex) { return false; }
    }

    void tick()
    {
        if (google == null && !configured()) return;
        try
        {
            if (google == null) google = new BattleshipSheets(credential);
            // Do not repeatedly read both complete teams, private fleets and
            // rewrite boards/timestamps while a different game is selected.
            List<List<List<Object>>> controls=google.batchValues(main,"Borddata!Z2","Zeeslagdata!A5","Instellingen!B10:F12");
            boolean disabled=!"Zeeslag".equals(text(controls.get(0),0,0))&&text(controls.get(1),0,0).isEmpty();
            String fingerprint=new com.google.gson.Gson().toJson(controls);
            if(disabled&&fingerprint.equals(disabledControls))return;
            sync(); lastError = "";
            disabledControls=disabled?fingerprint:"";
        }
        catch (Exception ex)
        {
            disabledControls="";
            // Never print Google response bodies, keys, placement values or private file IDs.
            String message = ex instanceof BattleshipGame.RuleFailure ? ex.getMessage() : "De zeeslagcontrole kon niet veilig worden afgerond. Controleer servertoegang, bladrechten en instellingen.";
            if (message == null) message = "Zeeslagcontrole mislukt";
            if (!message.equals(lastError)) { store.error("Zeeslag", message); lastError = message; }
            if (google != null) try
            {
                google.protect(main, Set.of(), Set.of());
                publish(null, List.of(Set.of(), Set.of()), "CONTROLE", message, new boolean[2]);
            }
            catch (Exception ignored) { /* Leave protected inputs closed on any read/write failure. */ }
        }
    }

    private void sync() throws Exception
    {
        google.protect(main, Set.of(), Set.of());
        BattleshipSheets.Access a = google.privateAccess(first), b = google.privateAccess(second);
        BattleshipSheets.separated(a, b);
        List<List<List<Object>>> root = google.batchValues(main, "Instellingen!B10:F12", "Instellingen!A17:G17", "Borddata!Z2", "Team 1!A5:R", "Team 2!A5:R", "Zeeslagdata!A5");
        long now = clock.getAsLong();
        String reset = text(root.get(5), 0, 0);
        if (!reset.isEmpty())
        {
            // Owner/service-only protected cell, written only after successful archive/reset.
            if (!reset.matches("RESET_V1:[a-fA-F0-9-]{36}") || !"".equals(cell(root.get(0),0,0)) || !"".equals(cell(root.get(0),0,4)))
                throw new BattleshipGame.RuleFailure("Resetbevestiging ongeldig: beide eventdatums moeten leeg zijn");
            store.retireBattleships(main + "@");
            clearPrivate(first); clearPrivate(second);
            google.sourceLocked(main, false, false);
            google.write(main, Map.of("Zeeslagdata!A5", List.of(List.of(""))));
            publish(null,List.of(Set.of(),Set.of()),"VOORBEREIDING","Event gereset; beide privévloten zijn leeg. Kies een spel en een nieuwe periode.",new boolean[]{true,true});
            return;
        }
        if (!(cell(root.get(0),0,0) instanceof Number) || !(cell(root.get(0),0,4) instanceof Number))
        {
            BattleshipGame old = store.latestBattleship(main + "@");
            if (old != null && old.started && now >= old.endsAt)
            {
                resetPrivate(first,old.key); resetPrivate(second,old.key);
                google.sourceLocked(main,false,false);
            }
            publish(null,List.of(Set.of(),Set.of()),"VOORBEREIDING","Vul start- en einddatum met tijd in. Er wordt niet geschoten.",new boolean[]{true,true});
            return;
        }
        if (!"Zeeslag".equals(text(root.get(2), 0, 0)))
        { publish(null, List.of(Set.of(), Set.of()), "UITGESCHAKELD", "Kies Zeeslag bij Instellingen. Er wordt niet geschoten.", new boolean[2]); return; }
        long start = date(cell(root.get(0), 0, 0)), end = date(cell(root.get(0), 0, 4));
        if (end <= start) throw new BattleshipGame.RuleFailure("Vul een geldige start- en einddatum met tijd in");
        String key = main + "@" + start + ":" + end;
        BattleshipGame game = store.battleship(key);
        if (game == null)
        {
            BattleshipGame sameStart = store.latestBattleship(main + "@" + start + ":");
            if (sameStart != null && (sameStart.started || now >= start)) game = sameStart;
        }
        if (game != null && game.retired) throw new BattleshipGame.RuleFailure("Dit event is gereset. Kies een nieuwe toekomstige starttijd.");
        if (game != null) key = game.key; // End-time changes never change the frozen fleet binding.
        if (game != null)
        {
            for (Map<String,Integer> fleet : game.fleets) for (String coordinate : fleet.keySet())
                if (!coordinate.matches("[A-H][1-8]")) throw new BattleshipGame.RuleFailure("De opgeslagen vloot past niet op het 8×8-bord. Bereid een nieuw event voor.");
            for (List<BattleshipGame.Shot> shots : game.shots) for (BattleshipGame.Shot shot : shots)
                if (!shot.coordinate.matches("[A-H][1-8]")) throw new BattleshipGame.RuleFailure("Het opgeslagen spel bevat schoten buiten het 8×8-bord. Bereid een nieuw event voor.");
        }
        BattleshipGame latest = store.activeBattleship(main + "@", now);
        if (latest != null && latest.started && now < latest.endsAt && !key.equals(latest.key))
            throw new BattleshipGame.RuleFailure("De vastgezette eventperiode is gewijzigd; herstel de oorspronkelijke periode");
        Progress progress = teamProgress(root.get(3), root.get(4), text(root.get(1), 0, 0), text(root.get(1), 0, 4));
        String binding = first + "\n" + second;
        if (game != null && now >= start && end != game.endsAt)
        {
            if (end > game.endsAt || now >= game.endsAt)
                throw new BattleshipGame.RuleFailure("Een gestart event kan alleen eerder worden beëindigd, niet heropend of verlengd");
            if (!binding.equals(game.binding) || !game.goals.equals(progress.goals) || !game.teamNames.equals(progress.names))
                throw new BattleshipGame.RuleFailure("Teamnamen, vloten of dropdoelen zijn na vastzetten gewijzigd");
            game.endsAt = end; store.saveBattleship(game);
        }
        if (now < start)
        {
            google.sourceLocked(main,false,false);
            try
            {
                google.privateLocked(first, false); google.privateLocked(second, false);
                List<List<String>> p1 = null, p2 = null;
                String error = null;
                try { p1 = placement(first, key); } catch (IllegalArgumentException e) { error = e.getMessage(); }
                try { p2 = placement(second, key); } catch (IllegalArgumentException e) { error = e.getMessage(); }
                if (error != null) throw new BattleshipGame.RuleFailure(error);
                BattleshipGame draft = BattleshipGame.create(key, start, end, progress.goals, p1, p2);
                draft.binding = binding; draft.teamNames = progress.names; draft.ready = true;
                if (game != null && game.started) throw new BattleshipGame.RuleFailure("Een gestart spel kan niet terug naar voorbereiding");
                store.saveBattleship(draft);
                publish(draft, progress.completed, "VOORBEREIDING", "Beide vloten zijn gereed. Schieten kan vanaf de starttijd.", new boolean[] {true, true});
            }
            catch (IllegalArgumentException | IllegalStateException failure)
            {
                if (game != null && !game.started) { game.ready = false; store.saveBattleship(game); }
                publish(null, progress.completed, "VOORBEREIDING", failure.getMessage(), new boolean[] {true, true});
            }
            return;
        }
        if (game == null || !game.ready)
        {
            if (now >= end) { publish(null, progress.completed, "AFGELOPEN", "Het event is beëindigd. Archiveren en resetten is mogelijk; er wordt niet geschoten.", new boolean[]{true,true}); return; }
            throw new BattleshipGame.RuleFailure("De server moet vóór de start beide complete vloten vastzetten. Plan een nieuwe toekomstige starttijd.");
        }
        if (!binding.equals(game.binding) || !game.goals.equals(progress.goals) || !game.teamNames.equals(progress.names))
            throw new BattleshipGame.RuleFailure("Vlootkoppeling, teamnamen of dropdoelen zijn na vastzetten gewijzigd");
        google.sourceLocked(main,true,Boolean.TRUE.equals(cell(root.get(0),2,0)));
        if (!game.started) { game.started = true; store.saveBattleship(game); }
        google.privateLocked(first, true); google.privateLocked(second, true);
        boolean[] consumed = new boolean[2];
        if (now < end && game.winner() == 0)
        {
            List<List<List<Object>>> inputs = google.batchValues(main, "Tussenstand!D65:H65", "Tussenstand!M65:Q65");
            List<String> targets = new ArrayList<>(Arrays.asList(null, null));
            for (int team = 0; team < 2; team++) if (Boolean.TRUE.equals(cell(inputs.get(team), 0, 4)))
            {
                consumed[team] = true;
                targets.set(team, text(inputs.get(team), 0, 0));
            }
            game.fireBatch(targets, progress.completed, clock.getAsLong());
            if (consumed[0] || consumed[1]) store.saveBattleship(game); // Commit before publishing; retries cannot double charge.
        }
        boolean active = clock.getAsLong() < end && game.winner() == 0;
        String message = active ? "Schieten kan met verdiende schoten; de bootopstellingen zijn vastgezet."
            : game.winner() == 0 ? "Het event is afgelopen. Er worden geen schoten meer verwerkt."
            : game.winner() == 3 ? "Gelijkspel: beide teams zonken de laatste boot in dezelfde verwerkingsronde."
            : game.teamNames.get(game.winner() - 1) + " wint: alle vijandelijke boten zijn gezonken.";
        publish(game, progress.completed, active ? "ACTIEF" : "AFGELOPEN", message, consumed);
        google.protect(main, active && game.available(0, progress.completed.get(0)) > 0 ? a.writers : Set.of(),
            active && game.available(1, progress.completed.get(1)) > 0 ? b.writers : Set.of());
    }

    private List<List<String>> placement(String file, String key) throws Exception
    {
        List<List<List<Object>>> data = google.batchValues(file, "Vloot!C6:D10", "Vloot!Q1", "Vloot!B17");
        String code = hash(key);
        if (!code.equals(text(data.get(1), 0, 0)))
        {
            google.write(file, Map.of("Vloot!Q1", List.of(List.of(code)), "Vloot!B17", List.of(List.of(false)),
                "Vloot!A2", List.of(List.of("Nieuw event gekoppeld. Controleer de boten en vink Gereed aan."))));
            throw new BattleshipGame.RuleFailure("Controleer beide privévloten en vink daar Gereed aan");
        }
        if (!Boolean.TRUE.equals(cell(data.get(2), 0, 0))) throw new BattleshipGame.RuleFailure("Beide leiders moeten hun privévloot Gereed melden");
        List<List<String>> out = new ArrayList<>();
        for (int n = 0; n < 5; n++) out.add(List.of(text(data.get(0), n, 0), text(data.get(0), n, 1)));
        return out;
    }

    private void resetPrivate(String file,String oldKey) throws Exception
    {
        List<List<List<Object>>> data=google.batchValues(file,"Vloot!Q1");
        if (!hash(oldKey).equals(text(data.get(0),0,0))) return;
        clearPrivate(file);
    }

    private void clearPrivate(String file) throws Exception
    {
        google.privateLocked(file,false);
        google.write(file,Map.of("Vloot!C6:D10",List.of(List.of("",""),List.of("",""),List.of("",""),List.of("",""),List.of("","")),
            "Vloot!Q1",List.of(List.of("")),"Vloot!B17",List.of(List.of(false)),"Vloot!A2",List.of(List.of("Event gereset. Plaats de boten voor het volgende event opnieuw."))));
    }

    private void publish(BattleshipGame game, List<Set<String>> complete, String phase, String message, boolean[] consumed) throws IOException
    {
        Map<String, List<List<?>>> data = new LinkedHashMap<>();
        data.put("Zeeslagdata!A2:A4", List.of(List.of(phase), List.of(message), List.of(Instant.ofEpochMilli(clock.getAsLong()).toString())));
        List<List<?>> counts = new ArrayList<>();
        for (int team = 0; team < 2; team++)
        {
            int earned = game == null ? 0 : game.earned(complete.get(team)), used = game == null ? 0 : game.shots.get(team).size();
            counts.add(List.of(team + 1, earned, used, Math.max(0, earned - used), game == null ? "" : game.messages.get(team)));
            data.put(team == 0 ? "Zeeslagdata!A12:J21" : "Zeeslagdata!M12:V21", sheetBoard(game, team));
            if (consumed[team])
            {
                data.put(team == 0 ? "Tussenstand!D65" : "Tussenstand!M65", List.of(List.of("")));
                data.put(team == 0 ? "Tussenstand!H65" : "Tussenstand!Q65", List.of(List.of(false)));
            }
        }
        data.put("Zeeslagdata!B8:F9", counts);
        google.write(main, data);
    }

    static final class Progress
    {
        final Map<String, Integer> goals = new LinkedHashMap<>();
        final List<Set<String>> completed = List.of(new HashSet<>(), new HashSet<>());
        final List<String> names;
        Progress(String a, String b) { names = List.of(a, b); }
    }

    static Progress progress(List<List<Object>> rows, String first, String second)
    {
        if (first.isEmpty() || second.isEmpty() || first.equalsIgnoreCase(second)) throw new BattleshipGame.RuleFailure("Vul twee verschillende teamnamen in");
        Progress p = new Progress(first, second);
        if (rows.isEmpty() || !"Drop-ID".equals(string(cell(rows, 0, 6)))) throw new BattleshipGame.RuleFailure("De screenshot-droplijst mist stabiele Drop-ID's");
        List<Map<String, Integer>> teams = List.of(new LinkedHashMap<>(), new LinkedHashMap<>());
        for (int r = 1; r < rows.size(); r++)
        {
            String item = text(rows, r, 0); if (item.isEmpty()) continue;
            String name = text(rows, r, 1), id = text(rows, r, 6);
            int team = first.equalsIgnoreCase(name) ? 0 : second.equalsIgnoreCase(name) ? 1 : -1;
            int goal = integer(cell(rows, r, 2)), obtained = integer(cell(rows, r, 3));
            if (team < 0 || !id.matches("DROP-[0-9]+") || goal < 1 || goal > 7 || obtained < 0 || obtained > goal
                || teams.get(team).putIfAbsent(id, goal) != null) throw new BattleshipGame.RuleFailure("Ongeldige of dubbele dropdoelregistratie");
            if (obtained == goal) p.completed.get(team).add(id);
        }
        if (teams.get(0).isEmpty() || teams.get(0).size() > 500 || !teams.get(0).equals(teams.get(1)))
            throw new BattleshipGame.RuleFailure("Beide teams moeten dezelfde geselecteerde dropdoelen hebben");
        p.goals.putAll(teams.get(0)); return p;
    }

    static Progress teamProgress(List<List<Object>> firstRows, List<List<Object>> secondRows, String first, String second)
    {
        if (first.isEmpty() || second.isEmpty() || first.equalsIgnoreCase(second)) throw new BattleshipGame.RuleFailure("Vul twee verschillende teamnamen in");
        Progress p = new Progress(first, second);
        List<List<List<Object>>> pages = List.of(firstRows, secondRows);
        List<Map<String,Integer>> goals = List.of(new LinkedHashMap<>(), new LinkedHashMap<>());
        for (int team = 0; team < 2; team++)
        {
            List<List<Object>> rows = pages.get(team);
            if (!"Drop-ID".equals(text(rows,0,0)) || !"Drop".equals(text(rows,0,1)) || !"Doel".equals(text(rows,0,2))
                || !"Behaald".equals(text(rows,0,10)) || !"Actief".equals(text(rows,0,17)))
                throw new BattleshipGame.RuleFailure("Teamblad mist de vaste kolommen Drop-ID, Drop, Doel, Behaald en Actief");
            for (int r = 1; r < rows.size(); r++)
            {
                Object active = cell(rows,r,17);
                if (Boolean.FALSE.equals(active) || "".equals(active)) continue;
                if (!Boolean.TRUE.equals(active)) throw new BattleshipGame.RuleFailure("Ongeldige dropselectie in teamblad");
                String id = text(rows,r,0), item = text(rows,r,1);
                int goal = integer(cell(rows,r,2)), obtained = integer(cell(rows,r,10));
                if (!id.matches("DROP-[0-9]+") || item.isEmpty() || item.length() > 100 || goal < 1 || goal > 7 || obtained < 0 || obtained > goal
                    || goals.get(team).putIfAbsent(id,goal) != null || goals.get(team).size() > 500)
                    throw new BattleshipGame.RuleFailure("Ongeldige of dubbele dropdoelregistratie in teamblad");
                if (obtained == goal) p.completed.get(team).add(id);
            }
        }
        if (goals.get(0).isEmpty() || !goals.get(0).equals(goals.get(1)))
            throw new BattleshipGame.RuleFailure("Beide teams moeten dezelfde geselecteerde dropdoelen hebben");
        p.goals.putAll(goals.get(0)); return p;
    }

    static long date(Object value)
    {
        if (!(value instanceof Number)) throw new BattleshipGame.RuleFailure("Vul eerst start- en einddatum met tijd in");
        double serial = ((Number) value).doubleValue();
        if (!Double.isFinite(serial) || serial < 43831 || serial >= 73416) throw new BattleshipGame.RuleFailure("Ongeldige eventdatum");
        long days = (long) Math.floor(serial), millis = Math.round((serial - days) * 86400000);
        LocalDateTime local = LocalDateTime.of(1899, 12, 30, 0, 0).plusDays(days).plusNanos(millis * 1000000);
        ZoneId zone = ZoneId.of("Europe/Amsterdam");
        if (zone.getRules().getValidOffsets(local).size() != 1) throw new BattleshipGame.RuleFailure("Kies een tijd buiten de zomertijdwisseling");
        return local.atZone(zone).toInstant().toEpochMilli();
    }

    private static int integer(Object value)
    {
        if (!(value instanceof Number)) return -1;
        double n = ((Number) value).doubleValue();
        return Double.isFinite(n) && n == Math.rint(n) && n >= 0 && n <= 500 ? (int) n : -1;
    }
    private static Object cell(List<List<Object>> rows, int r, int c) { return r < rows.size() && c < rows.get(r).size() ? rows.get(r).get(c) : ""; }
    private static String text(List<List<Object>> rows, int r, int c) { return string(cell(rows, r, c)); }
    private static String string(Object v) { return v instanceof String ? ((String) v).trim() : ""; }
    // Keep the existing transport ranges, explicitly clearing the removed rows/columns.
    static List<List<?>> sheetBoard(BattleshipGame game, int team)
    {
        List<List<?>> rows = new ArrayList<>();
        List<List<String>> board = game == null ? List.of() : game.publicBoard(team);
        for (int y = 0; y < 10; y++)
        {
            List<String> row = new ArrayList<>(java.util.Collections.nCopies(10, ""));
            if (game != null && y < BattleshipGame.SIZE)
                for (int x = 0; x < BattleshipGame.SIZE; x++) row.set(x, board.get(y).get(x));
            rows.add(row);
        }
        return rows;
    }
    private static String hash(String text) throws Exception { byte[] digest = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)); StringBuilder out = new StringBuilder(); for (byte b : digest) out.append(String.format("%02x", b)); return out.toString(); }
}

package nl.dutchnations.server;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Server-owned translations from event task labels to concrete loot item names. */
final class DropGroups
{
    private static final Map<String, Set<String>> ALIASES = createAliases();

    private DropGroups() { }

    /** null means the label is not a registered group; ordinary matching can handle it. */
    static Set<String> resolve(String label)
    {
        return label == null ? null : ALIASES.get(key(label));
    }

    private static String key(String label)
    {
        return label.replace('\u2019', '\'').trim().toLowerCase(Locale.ROOT)
            .replaceAll("\\s+", " ")
            .replaceFirst("^[0-9]+\\s*x\\s*", "")
            .replaceFirst("^any\\s+", "")
            .replaceAll("\\buniques\\b", "unique")
            .replaceAll("\\bunqiue\\b", "unique");
    }

    private static Map<String, Set<String>> createAliases()
    {
        Map<String, Set<String>> aliases = new LinkedHashMap<>();
        Set<String> ahrim = items("Ahrim's hood", "Ahrim's robetop", "Ahrim's robeskirt", "Ahrim's staff");
        Set<String> dharok = items("Dharok's helm", "Dharok's platebody", "Dharok's platelegs", "Dharok's greataxe");
        Set<String> guthan = items("Guthan's helm", "Guthan's platebody", "Guthan's chainskirt", "Guthan's warspear");
        Set<String> karil = items("Karil's coif", "Karil's leathertop", "Karil's leatherskirt", "Karil's crossbow");
        Set<String> torag = items("Torag's helm", "Torag's platebody", "Torag's platelegs", "Torag's hammers");
        Set<String> verac = items("Verac's helm", "Verac's brassard", "Verac's plateskirt", "Verac's flail");
        brother(aliases, ahrim, "ahrim");
        brother(aliases, dharok, "dharok");
        brother(aliases, guthan, "guthan");
        brother(aliases, karil, "karil");
        brother(aliases, torag, "torag");
        brother(aliases, verac, "verac");
        register(aliases, union(ahrim, dharok, guthan, karil, torag, verac),
            "barrows", "barrows piece", "barrows pieces", "barrows item", "barrows items", "barrows unique");
        // Historical spellings present in the supplied event spreadsheets.
        register(aliases, guthan, "guthans's set");
        register(aliases, items("Guthan's warspear"), "guthan's spear");
        register(aliases, items("Guthan's chainskirt"), "guthan's platelegs");

        Set<String> bloodMoon = items("Blood moon helm", "Blood moon chestplate", "Blood moon tassets", "Dual macuahuitl");
        Set<String> blueMoon = items("Blue moon helm", "Blue moon chestplate", "Blue moon tassets", "Blue moon spear");
        Set<String> eclipseMoon = items("Eclipse moon helm", "Eclipse moon chestplate", "Eclipse moon tassets", "Eclipse atlatl");
        register(aliases, bloodMoon, "blood moon set", "full blood moon", "blood moon unique", "blood moon piece", "blood moon pieces");
        register(aliases, blueMoon, "blue moon set", "full blue moon", "blue moon unique", "blue moon piece", "blue moon pieces");
        register(aliases, eclipseMoon, "eclipse moon set", "full eclipse moon", "eclipse moon unique", "eclipse moon piece", "eclipse moon pieces");
        register(aliases, union(bloodMoon, blueMoon, eclipseMoon), "moons", "moons of peril", "moons unique",
            "moons of peril unique", "moons piece", "moons pieces", "moon piece", "moon pieces", "piece moons", "pieces moons");

        Set<String> cox = items("Dexterous prayer scroll", "Arcane prayer scroll", "Twisted buckler",
            "Dragon hunter crossbow", "Dinh's bulwark", "Ancestral hat", "Ancestral robe top", "Ancestral robe bottom",
            "Dragon claws", "Elder maul", "Kodai insignia", "Twisted bow");
        Set<String> tob = items("Avernic defender hilt", "Ghrazi rapier", "Sanguinesti staff (uncharged)",
            "Justiciar faceguard", "Justiciar chestguard", "Justiciar legguards", "Scythe of vitur (uncharged)");
        Set<String> toa = items("Osmumten's fang", "Lightbearer", "Elidinis' ward", "Masori mask", "Masori body",
            "Masori chaps", "Tumeken's shadow (uncharged)");
        register(aliases, cox, "cox unique", "chambers unique", "chambers of xeric unique");
        register(aliases, tob, "tob unique", "theatre of blood unique");
        register(aliases, toa, "toa unique", "tombs of amascut unique");
        register(aliases, union(cox, tob, toa), "raid unique", "raids unique");

        register(aliases, items("Ancient hilt", "Nihil horn", "Zaryte vambraces", "Torva full helm (damaged)",
            "Torva platebody (damaged)", "Torva platelegs (damaged)"), "nex unique");
        register(aliases, items("Inquisitor's great helm", "Inquisitor's hauberk", "Inquisitor's plateskirt",
            "Inquisitor's mace", "Nightmare staff", "Volatile orb", "Harmonised orb", "Eldritch orb"),
            "nightmare unique", "the nightmare unique", "phosani unique", "phosani's nightmare unique");
        register(aliases, items("Oathplate helm", "Oathplate chest", "Oathplate legs", "Soulflame horn"), "yama unique");
        register(aliases, items("Avernic treads", "Eye of ayak (uncharged)", "Mokhaiotl cloth"),
            "doom unique", "doom of mokhaiotl unique", "mokhaiotl unique");
        register(aliases, items("Tormented synapse", "Burning claw"), "tormented demon unique", "tormented demons unique");
        register(aliases, items("Primordial crystal", "Pegasian crystal", "Eternal crystal", "Smouldering stone"),
            "cerb unique", "cerberus unique");
        register(aliases, items("Tanzanite fang", "Magic fang", "Serpentine visage", "Uncut onyx"), "zulrah unique");

        // Main unique table plus Awakener's orb. Quartz, one-time tablets, jars and pets are not included.
        register(aliases, items("Magus vestige", "Chromium ingot", "Eye of the duke", "Virtus mask",
            "Virtus robe top", "Virtus robe bottom", "Awakener's orb"),
            "duke unique", "duke sucellus unique", "duke unique geen quartz", "duke sucellus unique geen quartz");
        register(aliases, items("Ultor vestige", "Chromium ingot", "Executioner's axe head", "Virtus mask",
            "Virtus robe top", "Virtus robe bottom", "Awakener's orb"), "vardorvis unique", "vardorvis unique geen quartz");
        return Collections.unmodifiableMap(aliases);
    }

    private static void brother(Map<String, Set<String>> aliases, Set<String> items, String brother)
    {
        register(aliases, items, brother + " set", brother + "'s set", "full set " + brother,
            "full " + brother, brother + " piece", brother + " pieces", brother + " unique");
    }

    private static Set<String> items(String... names)
    {
        return Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(names)));
    }

    @SafeVarargs private static Set<String> union(Set<String>... groups)
    {
        Set<String> names = new LinkedHashSet<>();
        for (Set<String> group : groups) names.addAll(group);
        return Collections.unmodifiableSet(names);
    }

    private static void register(Map<String, Set<String>> aliases, Set<String> names, String... labels)
    {
        for (String label : labels)
        {
            if (aliases.putIfAbsent(key(label), names) != null)
                throw new IllegalStateException("Duplicate drop group alias: " + label);
        }
    }
}

