    static Map<String,Object> project(JsonObject input,boolean board,int row,int col,String mode,List<List<Object>> tiles,Map<String,String> icons) throws IOException
    {
        Map<String,Object> out=map();
        if(input.has("effectiveFormat"))out.put("userEnteredFormat",input.get("effectiveFormat"));
        JsonObject value=input.has("effectiveValue")?input.getAsJsonObject("effectiveValue"):new JsonObject();
        if(value.has("errorValue"))throw new IOException("De bron bevat een rekenfout");
        if(value.size()>0)out.put("userEnteredValue",value);
        String formula=input.has("userEnteredValue")&&input.getAsJsonObject("userEnteredValue").has("formulaValue")?input.getAsJsonObject("userEnteredValue").get("formulaValue").getAsString():"";
        if(board&&formula.contains("IMAGE(")&&gridMode(mode))
        {
            Matcher modes=Pattern.compile("NOT\\(OR\\(([^)]*)\\)\\)").matcher(formula);
            if(modes.find()&&!modes.group(1).contains("\""+mode+"\""))return out;
            Matcher index=Pattern.compile("IF\\(Borddata!\\$Z\\$2=\"Bingo\";([0-9]+);([0-9]+)\\)").matcher(formula);
            if(index.find())
            {
                int tile=Integer.parseInt(index.group(mode.equals("Bingo")?1:2));
                String url=icons.getOrDefault(string(tiles,tile-1,0),"");
                if(url.matches("https://(?:oldschool\\.runescape\\.wiki|static\\.runelite\\.net|secure\\.runescape\\.com)/[^\"\\s]+"))
                    out.put("userEnteredValue",map("formulaValue","=IMAGE(\""+url+"\";1)"));
            }
        }
        if(formula.startsWith("=HYPERLINK("))
        {
            Matcher link=Pattern.compile("HYPERLINK\\(\"([^\"]+)\";\"([^\"]+)\"\\)").matcher(formula);
            if(link.find()&&(link.group(1).matches("#gid=(1058026847|1726059411|1726059412)(?:&range=[A-Z0-9:]+)?")
                ||link.group(1).startsWith("https://docs.google.com/document/d/"))) out.put("userEnteredValue",map("formulaValue","=HYPERLINK(\""+link.group(1)+"\";\""+link.group(2)+"\")"));
            else out.remove("userEnteredValue");
        }
        if(board&&row==64&&(col==3||col==4||col==7||col==12||col==13||col==16))out.remove("userEnteredValue");
        if(board&&row==70&&col==0)out.put("userEnteredValue",map("stringValue","Teamleiders schieten in het basisbestand. Dit kijkbestand is alleen-lezen."));
        if(!board&&col==0&&row==0)out.put("userEnteredValue",map("stringValue","Alleen-lezen ledenweergave. Registraties worden in het basisbestand bijgehouden."));
        if(!board&&col==0&&row==1&&value.has("stringValue"))out.put("userEnteredValue",map("stringValue",value.get("stringValue").getAsString().replace("teamoverzicht & invoer","dropvoortgang")));
        if(!board&&col==0&&row==3)out.put("userEnteredValue",map("stringValue","Hier zie je de automatisch bijgewerkte teamvoortgang. Spelleiders registreren drops in het basisbestand."));
        return out;
    }
    private static JsonArray array(JsonObject o,String key){return o!=null&&o.has(key)?o.getAsJsonArray(key):new JsonArray();}
}

package nl.dutchnations.server;

import com.google.auth.oauth2.GoogleCredentials;
import com.google.auth.oauth2.ServiceAccountCredentials;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads drop names from the event Sheet; it never writes to Google. */
final class GoogleSheetDrops
{
    private static final String SCOPE = "https://www.googleapis.com/auth/spreadsheets.readonly";
    private static final Pattern PATH = Pattern.compile("^/spreadsheets/d/([A-Za-z0-9_-]{20,128})(?:/.*)?$");
    private static final Pattern GID = Pattern.compile("(?:^|&)gid=([0-9]{1,20})(?:&|$)");
    private static final int MAX_BYTES = 1024 * 1024;
    private static final int MAX_ITEMS = 500;
    private static GoogleCredentials credentials;

    private GoogleSheetDrops() { }

    static String sheetId(String url)
    {
        if (url == null || url.length() > 2000) return null;
        try
        {
            URI uri = URI.create(url.trim());
            if (!"https".equalsIgnoreCase(uri.getScheme()) || !"docs.google.com".equalsIgnoreCase(uri.getHost())
                || uri.getUserInfo() != null || (uri.getPort() != -1 && uri.getPort() != 443)) return null;
            Matcher match = PATH.matcher(uri.getRawPath());
            return match.matches() ? match.group(1) : null;
        }
        catch (RuntimeException ex) { return null; }
    }

    static Set<String> fetch(String link) throws IOException
    {
        String id = sheetId(link);
        if (id == null) throw new IOException("Geen ondersteunde Google Sheets-link");
        // A specific tab can place its catalog next to other tables. Native CSV
        // preserves row-six headers and empty cells that GViz may coerce away.
        if (tabKey(link) != null)
        {
            try { return parseCsv(new String(readTeamExport(teamExportUri(link)), StandardCharsets.UTF_8)); }
            catch (IOException ignored) { /* Keep the established public/private fallbacks. */ }
        }
        // Een openbare Sheet heeft geen Google-account of service-account nodig.
        // Probeer die route eerst, zodat de eventbeheerder niets extra's hoeft te delen.
        try
        {
            URI publicCsv = publicCsv(link, id);
            return parseCsv(new String(read(publicCsv, null), StandardCharsets.UTF_8));
        }
        catch (IOException publicFailure)
        {
            return fetchPrivate(id, publicFailure);
        }
    }

    static Set<String> fetch(String link, String teamNames) throws IOException
    {
        if (EventTeams.names(teamNames).isEmpty()) return fetch(link);
        String id = sheetId(link);
        if (id == null) throw new IOException("Geen ondersteunde Google Sheets-link voor teams");
        // Team events deliberately read exactly the selected public tab, never a
        // different private fallback range which could omit team columns.
        return parseTeamCsv(new String(read(publicCsv(link, id), null), StandardCharsets.UTF_8), teamNames);
    }

    static String tabKey(String link)
    {
        String id = sheetId(link);
        if (id == null) return null;
        URI uri = URI.create(link.trim());
        Matcher query = GID.matcher(uri.getRawQuery() == null ? "" : uri.getRawQuery());
        Matcher fragment = GID.matcher(uri.getRawFragment() == null ? "" : uri.getRawFragment());
        String q = query.find() ? query.group(1) : null, f = fragment.find() ? fragment.group(1) : null;
        if (q != null && f != null && !q.equals(f)) return null;
        return q == null && f == null ? null : id + "/" + (q == null ? f : q);
    }

    static Set<String> fetch(String link, String teamNames, String one, String two) throws IOException
    { return fetch(link,teamNames,one,two,null); }

    static Set<String> fetch(String link, String teamNames, String one, String two, String three) throws IOException
    {
        if ((one == null || one.trim().isEmpty()) && (two == null || two.trim().isEmpty()) && (three == null || three.trim().isEmpty())) return fetch(link, teamNames);
        String error = EventTeams.validatePages("CLAN_EVENT", teamNames, one, two, three);
        if (error != null) throw new IOException(error);
        List<String> teams = EventTeams.names(teamNames);
        Set<String> available = new LinkedHashSet<>();
        String[] pages = three==null||three.trim().isEmpty()?new String[]{one,two}:new String[]{one,two,three};
        for (int i = 0; i < pages.length; i++)
            available.addAll(fetchTeamPage(pages[i],teams.get(i)));
        if (available.size() > MAX_ITEMS) throw new IOException("Te veel beschikbare teamdrops");
        return Collections.unmodifiableSet(available);
    }

    static Set<String> fetchTeamPage(String link, String team) throws IOException
    {
        String id = sheetId(link);
        if (id == null) throw new IOException("Geen ondersteunde teamdroppagina");
        return parseTeamInputCsv(new String(readTeamExport(teamExportUri(link)), StandardCharsets.UTF_8), team);
    }

    // gviz guesses and merges header rows and drops minority-type header cells.
    // A native CSV export keeps the title and Drop/Doel/Behaald/Actief intact.
    static URI teamExportUri(String link) throws IOException
    {
        String key=tabKey(link);
        if(key==null)throw new IOException("Teamdroppagina vereist een expliciete gid");
        int split=key.indexOf('/');
        return URI.create("https://docs.google.com/spreadsheets/d/"+key.substring(0,split)+"/export?format=csv&gid="+key.substring(split+1));
    }

    static boolean allowedExportRedirect(URI uri)
    {
        return uri!=null&&"https".equalsIgnoreCase(uri.getScheme())&&uri.getHost()!=null
            &&uri.getHost().matches("[a-z0-9-]+-sheets\\.googleusercontent\\.com")&&uri.getUserInfo()==null
            &&(uri.getPort()==-1||uri.getPort()==443)&&uri.getFragment()==null;
    }

    private static byte[] readTeamExport(URI uri) throws IOException
    {
        // Only this PUBLIC, unauthenticated export follows Google's download hop.
        // Never forward a credential or follow a login/third-party redirect.
        for(int hop=0;hop<3;hop++)
        {
            HttpURLConnection connection=(HttpURLConnection)uri.toURL().openConnection();
            connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(6000);connection.setReadTimeout(10000);
            try
            {
                int status=connection.getResponseCode();
                if(status==302||status==303||status==307||status==308)
                {
                    URI next;
                    try{String location=connection.getHeaderField("Location");next=location==null?null:uri.resolve(location);}
                    catch(IllegalArgumentException invalid){throw new IOException("Ongeldige Google-exportverwijzing");}
                    if(!allowedExportRedirect(next))throw new IOException("Teamdroppagina is niet openbaar bereikbaar");
                    uri=next;continue;
                }
                if(status!=200)throw new IOException("Teamdroppagina gaf HTTP "+status);
                try(java.io.InputStream input=connection.getInputStream())
                {
                    byte[] bytes=input.readNBytes(MAX_BYTES+1);
                    if(bytes.length>MAX_BYTES)throw new IOException("Sheetgegevens zijn te groot");
                    return bytes;
                }
            }finally{connection.disconnect();}
        }
        throw new IOException("Te veel Google-exportverwijzingen");
    }

    /** The native event template: active rows only, validated counts, no write-back. */
    static Set<String> parseTeamInputCsv(String csv, String expectedTeam) throws IOException
    {
        List<List<String>> rows = csvRows(csv);
        boolean named = false;
        for (List<String> row : rows)
            if (!row.isEmpty() && (row.get(0).trim().equalsIgnoreCase(expectedTeam + " — teamoverzicht & invoer")
                || row.get(0).trim().equalsIgnoreCase(expectedTeam + " — dropvoortgang"))) named = true;
        if (!named) throw new IOException("Teamnaam in de droppagina komt niet overeen met het event");
        for (int index = 0; index < rows.size(); index++)
        {
            List<String> header = rows.get(index);
            int id = column(header, "drop-id"), item = column(header, "drop"), goal = column(header, "doel");
            int count = column(header, "behaald"), active = column(header, "actief"), status = column(header, "status");
            if (id < 0 || item < 0 || goal < 0 || count < 0 || active < 0 || status < 0) continue;
            Set<String> seen = new LinkedHashSet<>(), available = new LinkedHashSet<>();
            for (int r = index + 1; r < rows.size(); r++)
            {
                List<String> row = rows.get(r);
                String selected = cell(row, active);
                if (selected.isEmpty() || "false".equalsIgnoreCase(selected) || "onwaar".equalsIgnoreCase(selected)) continue;
                if (!"true".equalsIgnoreCase(selected) && !"waar".equalsIgnoreCase(selected)) throw new IOException("Ongeldige selectie in teamdroppagina");
                String key = cell(row, id), name = cell(row, item);
                if (!key.matches("DROP-[0-9]+") || !seen.add(key)) throw new IOException("Ongeldig of dubbel Drop-ID in teamdroppagina");
                if (name.isEmpty() || name.length() > 100 || name.indexOf(';') >= 0 || name.chars().anyMatch(Character::isISOControl)) throw new IOException("Ongeldige dropnaam in teamdroppagina");
                int target = teamNumber(cell(row, goal), false), obtained = teamNumber(cell(row, count), true);
                if (target > 7 || obtained > target) throw new IOException("Doel moet 1 t/m 7 zijn; Behaald mag niet boven het doel liggen");
                String state = cell(row, status);
                if (obtained < target && "nog nodig".equalsIgnoreCase(state)) addResolved(available, name, name);
                else if (obtained < target && !state.toLowerCase(Locale.ROOT).startsWith("van ")) throw new IOException("Onbekende status in teamdroppagina");
                if (seen.size() > MAX_ITEMS) throw new IOException("Te veel actieve teamdrops");
            }
            return Collections.unmodifiableSet(available);
        }
        throw new IOException("Teamdroppagina vereist Drop-ID, Drop, Doel, Behaald, Status en Actief");
    }

    static Set<String> parseTeamCsv(String csv, String teamNames) throws IOException
    {
        List<String> teams = EventTeams.names(teamNames);
        if (teams.isEmpty()) return parseCsv(csv);
        List<List<String>> rows = csvRows(csv);
        for (int index = 0; index < rows.size(); index++)
        {
            List<String> header = rows.get(index);
            int itemColumn = column(header, "drop (bewerkbaar)");
            int teamColumn = column(header, "team");
            int goalColumn = column(header, "doel");
            int countColumn = column(header, "behaald");
            if (itemColumn < 0 || teamColumn < 0 || goalColumn < 0 || countColumn < 0) continue;
            Set<String> seenTeams = new LinkedHashSet<>();
            Set<String> seenRows = new LinkedHashSet<>();
            Set<String> available = new LinkedHashSet<>();
            for (int rowIndex = index + 1; rowIndex < rows.size(); rowIndex++)
            {
                List<String> row = rows.get(rowIndex);
                String item = cell(row, itemColumn), team = cell(row, teamColumn);
                if (item.isEmpty() && team.isEmpty() && cell(row, goalColumn).isEmpty() && cell(row, countColumn).isEmpty()) continue;
                String key = team.toLowerCase(Locale.ROOT);
                if (teams.stream().noneMatch(name -> name.equalsIgnoreCase(team)))
                    throw new IOException("Onbekend of leeg team in droplijst: " + team);
                if (item.isEmpty() || item.length() > 100 || item.indexOf(';') >= 0 || item.chars().anyMatch(Character::isISOControl))
                    throw new IOException("Ongeldige dropnaam in teamdroplijst");
                if (!seenRows.add(key + "\n" + item.replace('\u2019', '\'').toLowerCase(Locale.ROOT)))
                    throw new IOException("Dubbele drop voor hetzelfde team");
                seenTeams.add(key);
                int goal = teamNumber(cell(row, goalColumn), false);
                String count = cell(row, countColumn);
                int obtained = count.isEmpty() ? 0 : teamNumber(count, true);
                if (obtained < goal) addResolved(available, item, item);
            }
            if (seenRows.size() > MAX_ITEMS * teams.size()) throw new IOException("Te veel teamdrops");
            if (seenTeams.size() != teams.size()) throw new IOException("Niet alle ingestelde teams staan in de droplijst");
            return Collections.unmodifiableSet(available);
        }
        throw new IOException("Teamdroplijst vereist kolommen Drop (bewerkbaar), Team, Doel en Behaald");
    }

    private static String cell(List<String> row, int column)
    { return row.size() <= column ? "" : row.get(column).trim(); }

    private static int teamNumber(String value, boolean allowZero) throws IOException
    {
        if (!value.matches("[0-9]{1,7}")) throw new IOException("Doel en Behaald moeten hele aantallen zijn");
        int number = Integer.parseInt(value);
        if (number > 1000000 || (!allowZero && number == 0)) throw new IOException("Ongeldig doel of behaald aantal");
        return number;
    }

    private static URI publicCsv(String link, String id)
    {
        URI original = URI.create(link.trim());
        Matcher gid = GID.matcher(original.getRawQuery() == null ? "" : original.getRawQuery());
        Matcher fragment = GID.matcher(original.getRawFragment() == null ? "" : original.getRawFragment());
        String tab = gid.find() ? "gid=" + gid.group(1) : fragment.find() ? "gid=" + fragment.group(1) : "sheet=Instellingen";
        return URI.create("https://docs.google.com/spreadsheets/d/" + id + "/gviz/tq?tqx=out:csv&" + tab);
    }

    static SheetTeamRoster fetchRoster(String id) throws IOException
    { return fetchRoster(id,2); }

    static SheetTeamRoster fetchRoster(String id,int teamCount) throws IOException
    {
        return SheetTeamRoster.parseCsv(new String(read(rosterUri(id,teamCount), null, 2500, 4000), StandardCharsets.UTF_8),teamCount);
    }

    static URI rosterUri(String id,int teamCount) throws IOException
    {
        if (id == null || !id.matches("[A-Za-z0-9_-]{20,128}")) throw new IOException("Ongeldig Sheet-id voor teamindeling");
        if(teamCount<2||teamCount>3)throw new IOException("Ongeldig aantal aparte teams");
        return URI.create("https://docs.google.com/spreadsheets/d/" + id
            + "/gviz/tq?tqx=out:csv&sheet=Instellingen&range=A17%3A"+(teamCount==2?"E":"I")+"1018&tq=select%20A%2CE"+(teamCount==3?"%2CI":"")+"&headers=0");
    }

    private static Set<String> fetchPrivate(String id, IOException publicFailure) throws IOException
    {
        String jsonKey = System.getenv("DN_GOOGLE_SERVICE_ACCOUNT_JSON");
        if (jsonKey == null || jsonKey.trim().isEmpty() || jsonKey.length() > 50000)
            throw new IOException("Sheet is niet openbaar bereikbaar; deel hem openbaar of stel Google-leestoegang in", publicFailure);
        GoogleCredentials access = credentials(jsonKey);
        access.refreshIfExpired();
        if (access.getAccessToken() == null) throw new IOException("Google-leestoegang niet beschikbaar");
        URI api = URI.create("https://sheets.googleapis.com/v4/spreadsheets/" + id + "/values/Instellingen%21G3%3AH1000");
        return parse(new String(read(api, "Bearer " + access.getAccessToken().getTokenValue()), StandardCharsets.UTF_8));
    }

    private static byte[] read(URI uri, String authorization) throws IOException
    { return read(uri, authorization, 6000, 10000); }

    private static byte[] read(URI uri, String authorization, int connectTimeout, int readTimeout) throws IOException
    {
        HttpURLConnection connection = (HttpURLConnection) uri.toURL().openConnection();
        connection.setConnectTimeout(connectTimeout); connection.setReadTimeout(readTimeout);
        connection.setInstanceFollowRedirects(false);
        if (authorization != null) connection.setRequestProperty("Authorization", authorization);
        try
        {
            if (connection.getResponseCode() != 200) throw new IOException("Sheet gaf HTTP " + connection.getResponseCode());
            byte[] bytes;
            try (java.io.InputStream input = connection.getInputStream()) { bytes = input.readNBytes(MAX_BYTES + 1); }
            if (bytes.length > MAX_BYTES) throw new IOException("Sheetgegevens zijn te groot");
            return bytes;
        }
        finally { connection.disconnect(); }
    }

    private static synchronized GoogleCredentials credentials(String jsonKey) throws IOException
    {
        if (credentials != null) return credentials;
        try (ByteArrayInputStream key = new ByteArrayInputStream(jsonKey.getBytes(StandardCharsets.UTF_8)))
        {
            credentials = ServiceAccountCredentials.fromStream(key).createScoped(Collections.singleton(SCOPE));
        }
        return credentials;
    }

    static Set<String> parse(String json) throws IOException
    {
        try
        {
            JsonObject data = JsonParser.parseString(json).getAsJsonObject();
            JsonArray rows = data.getAsJsonArray("values");
            if (rows == null || rows.size() < 2) throw new IOException("Geen droplijst gevonden");
            List<List<String>> table = new ArrayList<>();
            for (int i = 1; i < rows.size(); i++)
            {
                JsonElement value = rows.get(i);
                if (!value.isJsonArray()) throw new IOException("Ongeldige rij in droplijst");
                JsonArray row = value.getAsJsonArray();
                List<String> values = new ArrayList<>();
                for (JsonElement cell : row) values.add(cell.isJsonNull() ? "" : cell.getAsString());
                table.add(values);
            }
            JsonArray header = rows.get(0).getAsJsonArray();
            List<String> headerValues = new ArrayList<>();
            for (JsonElement cell : header) headerValues.add(cell.isJsonNull() ? "" : cell.getAsString());
            table.add(0, headerValues);
            return parseTable(table);
        }
        catch (IOException ex) { throw ex; }
        catch (RuntimeException ex) { throw new IOException("Sheetgegevens hebben een onbekende indeling", ex); }
    }

    static Set<String> parseCsv(String csv) throws IOException
    {
        return parseTable(csvRows(csv));
    }

    private static Set<String> parseTable(List<List<String>> rows) throws IOException
    {
        Set<String> pvmWarItems = parsePvmWarLayout(rows);
        if (pvmWarItems != null) return pvmWarItems;
        Set<String> checkboxItems = parseCheckboxLayout(rows);
        if (checkboxItems != null) return checkboxItems;
        int headerRow = -1;
        int itemColumn = -1;
        for (int rowIndex = 0; rowIndex < rows.size() && headerRow == -1; rowIndex++)
        {
            List<String> row = rows.get(rowIndex);
            for (int column = 0; column + 1 < row.size(); column++)
            {
                if ("drop (bewerkbaar)".equals(row.get(column).replace("\ufeff", "").trim().toLowerCase(Locale.ROOT))
                    && "doel".equals(row.get(column + 1).trim().toLowerCase(Locale.ROOT)))
                { headerRow = rowIndex; itemColumn = column; break; }
            }
        }
        if (headerRow == -1)
            throw new IOException("Sheet heeft niet de verwachte indeling");
        Set<String> names = new LinkedHashSet<>();
        Set<String> normalized = new LinkedHashSet<>();
        for (int i = headerRow + 1; i < rows.size(); i++)
        {
            List<String> row = rows.get(i);
            String item = row.size() <= itemColumn ? "" : row.get(itemColumn).trim();
            if (item.isEmpty()) continue;
            if (item.length() > 100 || item.indexOf(';') >= 0 || item.chars().anyMatch(Character::isISOControl))
                throw new IOException("Ongeldige dropnaam in sheet");
            String key = item.replace('\u2019', '\'').toLowerCase(Locale.ROOT);
            if (!normalized.add(key)) throw new IOException("Dubbele drops in sheet");
            addResolved(names, item, item);
        }
        if (names.isEmpty()) throw new IOException("Geen dropnamen gevonden");
        return Collections.unmodifiableSet(names);
    }

    /**
     * Supports the public PvM War format: an Item name column plus numbered
     * obtained-by columns. A row is no longer eligible after seven entries.
     */
    private static Set<String> parsePvmWarLayout(List<List<String>> rows) throws IOException
    {
        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++)
        {
            List<String> header = rows.get(rowIndex);
            int itemColumn = column(header, "item name");
            int pointsColumn = column(header, "points");
            List<Integer> obtainedColumns = new ArrayList<>();
            for (int slot = 1; slot <= 7; slot++)
            {
                int index = column(header, "#" + slot + " obtained by");
                if (index >= 0) obtainedColumns.add(index);
            }
            if (itemColumn < 0 || obtainedColumns.size() != 7) continue;

            Set<String> names = new LinkedHashSet<>();
            Set<String> normalized = new LinkedHashSet<>();
            for (int i = rowIndex + 1; i < rows.size(); i++)
            {
                List<String> row = rows.get(i);
                if (pointsColumn >= 0 && (row.size() <= pointsColumn || !row.get(pointsColumn).trim().matches("[0-9]+"))) continue;
                String item = row.size() <= itemColumn ? "" : row.get(itemColumn).replaceAll("\\s+", " ").trim();
                if (item.isEmpty()) continue;
                if (item.length() > 100 || item.indexOf(';') >= 0 || item.chars().anyMatch(Character::isISOControl))
                    throw new IOException("Ongeldige dropnaam in sheet");
                int obtained = 0;
                for (int index : obtainedColumns) if (present(row, index)) obtained++;
                if (obtained >= 7) continue;
                String key = item.replace('\u2019', '\'').toLowerCase(Locale.ROOT);
                if (!normalized.add(key)) continue;
                addResolved(names, item, item);
            }
            return Collections.unmodifiableSet(names);
        }
        return null;
    }

    /** Bingo tasks use literal names or a name fragment; no boss drop tables are inferred. */
    private static Set<String> parseCheckboxLayout(List<List<String>> rows) throws IOException
    {
        for (int headerRow = 0; headerRow < rows.size(); headerRow++)
        {
            List<String> header = rows.get(headerRow);
            int itemColumn = column(header, "item");
            if (itemColumn < 0)
            {
                int amountColumn = column(header, "aantal");
                if (amountColumn < 2 || headerRow + 1 >= rows.size()
                    || rows.get(headerRow + 1).size() <= amountColumn
                    || !"1".equals(rows.get(headerRow + 1).get(amountColumn).trim())) continue;
                itemColumn = amountColumn - 2;
            }
            Set<String> tasks = new LinkedHashSet<>();
            boolean foundCheckbox = false;
            for (int rowIndex = headerRow + 1; rowIndex < rows.size(); rowIndex++)
            {
                List<String> row = rows.get(rowIndex);
                if (row.size() <= itemColumn + 1) continue;
                String item = row.get(itemColumn).trim();
                String checked = row.get(itemColumn + 1).trim();
                if (item.isEmpty() || !("TRUE".equalsIgnoreCase(checked) || "FALSE".equalsIgnoreCase(checked))) continue;
                foundCheckbox = true;
                if ("TRUE".equalsIgnoreCase(checked)) continue;
                if (item.length() > 100 || item.indexOf(';') >= 0 || item.chars().anyMatch(Character::isISOControl))
                    throw new IOException("Ongeldige dropomschrijving in sheet");
                addResolved(tasks, item, taskRule(item));
            }
            if (foundCheckbox) return Collections.unmodifiableSet(tasks);
        }
        return null;
    }

    private static void addResolved(Set<String> names, String label, String fallback) throws IOException
    {
        Set<String> group = DropGroups.resolve(label);
        if (group == null) names.add(fallback);
        else names.addAll(group);
        if (names.size() > MAX_ITEMS) throw new IOException("Te veel drops in sheet");
    }

    private static String taskRule(String task)
    {
        Matcher explicit = Pattern.compile("^(?:bevat|contains)\\s*:\\s*(.+)$", Pattern.CASE_INSENSITIVE).matcher(task);
        if (explicit.matches()) return "@namecontains:" + explicit.group(1).trim();
        Matcher piece = Pattern.compile("^(?:[0-9]+\\s*x\\s*)?(?:any\\s+)?(.+?)\\s+(?:armou?r\\s+)?pieces?$", Pattern.CASE_INSENSITIVE).matcher(task);
        if (piece.matches()) return "@namecontains:" + piece.group(1).trim();
        return "@contains:" + task;
    }

    static boolean matchesItem(String rule, String item)
    {
        if (rule == null || item == null || item.trim().isEmpty()) return false;
        String name = item.trim().replace('\u2019', '\'').toLowerCase(Locale.ROOT);
        String selected = rule.trim().replace('\u2019', '\'').toLowerCase(Locale.ROOT);
        if (selected.startsWith("@namecontains:"))
        {
            String fragment = selected.substring("@namecontains:".length()).trim();
            return !fragment.isEmpty() && Pattern.compile("(?<![\\p{L}\\p{N}])" + Pattern.quote(fragment) + "(?![\\p{L}\\p{N}])")
                .matcher(name).find();
        }
        if (!selected.startsWith("@contains:")) return selected.equals(name);
        return Pattern.compile("(?<![\\p{L}\\p{N}'])" + Pattern.quote(name) + "(?![\\p{L}\\p{N}'])")
            .matcher(selected.substring("@contains:".length())).find();
    }

    private static int column(List<String> header, String name)
    {
        for (int i = 0; i < header.size(); i++)
            if (name.equals(header.get(i).replace("\ufeff", "").trim().toLowerCase(Locale.ROOT))) return i;
        return -1;
    }

    private static boolean present(List<String> row, int column)
    { return column >= 0 && row.size() > column && !row.get(column).trim().isEmpty(); }

    static List<List<String>> csvRows(String csv) throws IOException
    {
        List<List<String>> rows = new ArrayList<>(); List<String> row = new ArrayList<>(); StringBuilder cell = new StringBuilder(); boolean quoted = false;
        for (int i = 0; i < csv.length(); i++)
        {
            char value = csv.charAt(i);
            if (value == '"')
            {
                if (quoted && i + 1 < csv.length() && csv.charAt(i + 1) == '"') { cell.append(value); i++; }
                else quoted = !quoted;
            }
            else if (value == ',' && !quoted) { row.add(cell.toString()); cell.setLength(0); }
            else if ((value == '\n' || value == '\r') && !quoted)
            {
                if (value == '\r' && i + 1 < csv.length() && csv.charAt(i + 1) == '\n') i++;
                row.add(cell.toString()); cell.setLength(0); rows.add(row); row = new ArrayList<>();
            }
            else cell.append(value);
        }
        if (quoted) throw new IOException("Ongeldige CSV in Sheet");
        if (cell.length() > 0 || !row.isEmpty()) { row.add(cell.toString()); rows.add(row); }
        return rows;
    }
}

package nl.dutchnations.server;

import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.io.StringReader;
import java.net.HttpURLConnection;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.Enumeration;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.swing.text.MutableAttributeSet;
import javax.swing.text.html.HTML;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.parser.ParserDelegator;

/** Read-only, local-test view of the public PvM War progress. */
final class PvmWarProgress
{
    static final String SOURCE = "PVM_WAR_2026";
    private static final URI PAGE = URI.create("https://osrs-nlbe.com/author/dutch_nation/pvm-war-2026/");
    private static final int MAX_PAGE_BYTES = 2_000_000;
    private final Map<String, Slots> items;

    private PvmWarProgress(Map<String, Slots> items) { this.items = items; }

    static PvmWarProgress fetch() throws IOException
    {
        HttpURLConnection connection = (HttpURLConnection) PAGE.toURL().openConnection();
        connection.setConnectTimeout(6000);
        connection.setReadTimeout(10000);
        connection.setInstanceFollowRedirects(false);
        connection.setRequestProperty("User-Agent", "DutchNationLocalDropTest/1.0");
        try
        {
            if (connection.getResponseCode() != 200) throw new IOException("PvM War-pagina niet beschikbaar");
            byte[] page;
            try (InputStream body = connection.getInputStream()) { page = body.readNBytes(MAX_PAGE_BYTES + 1); }
            if (page.length > MAX_PAGE_BYTES) throw new IOException("PvM War-pagina te groot");
            PvmWarProgress progress = parse(new String(page, StandardCharsets.UTF_8));
            // Reject error pages or changed layouts; missing items must never silently become zero.
            if (progress.items.size() < 100 || progress.lookup("Jar Tier 1") == null
                || progress.lookup("Dragon claws") == null)
                throw new IOException("PvM War-pagina heeft een onbekende indeling");
            return progress;
        }
        finally { connection.disconnect(); }
    }

    static PvmWarProgress parse(String html) throws IOException
    {
        Map<String, Slots> result = new HashMap<>();
        HTMLEditorKit.ParserCallback callback = new HTMLEditorKit.ParserCallback()
        {
            String item;
            int cells, approved, waiting;
            boolean title, invalid;

            @Override public void handleStartTag(HTML.Tag tag, MutableAttributeSet attributes, int position)
            {
                if (tag == HTML.Tag.TR)
                {
                    item = attr(attributes, "data-item"); cells = 0; approved = 0; waiting = 0;
                    title = false; invalid = false;
                }
                else if (item != null && tag == HTML.Tag.TD)
                {
                    cells++;
                    if (cells > 1)
                    {
                        String css = attr(attributes, "class");
                        css = css == null ? "" : css.trim();
                        if ("approved".equals(css)) approved++;
                        else if ("waiting".equals(css)) waiting++;
                        else if (!css.isEmpty()) invalid = true;
                    }
                }
                else if (item != null && tag == HTML.Tag.SPAN)
                {
                    String css = attr(attributes, "class");
                    if (css != null && (" " + css + " ").contains(" item-name__title ")) title = true;
                }
            }

            @Override public void handleEndTag(HTML.Tag tag, int position)
            {
                if (tag == HTML.Tag.TR && item != null)
                {
                    if (title && cells == 4 && !invalid && approved + waiting <= 3)
                    {
                        String key = normalize(item);
                        // Duplicates are ambiguous; reject them rather than assuming availability.
                        if (result.containsKey(key)) result.put(key, new Slots(-1, -1));
                        else result.put(key, new Slots(approved, waiting));
                    }
                    item = null;
                }
            }
        };
        try (Reader reader = new StringReader(html)) { new ParserDelegator().parse(reader, callback, true); }
        return new PvmWarProgress(result);
    }

    Slots lookup(String item)
    {
        if (item == null) return null;
        String key = normalize(item);
        if (key.startsWith("jar of "))
        {
            String name = key.substring("jar of ".length());
            if ("|dreams|spirits|stone|".contains("|" + name + "|")) key = "jar tier 1";
            else if (("|chemicals|decay|sand|souls|swamp|venom|").contains("|" + name + "|")) key = "jar tier 2";
            else if (("|dirt|eyes|feathers|light|miasma|smoke|").contains("|" + name + "|")) key = "jar tier 3";
        }
        Slots slots = items.get(key);
        return slots == null || slots.approved < 0 ? null : slots;
    }

    /** Live item names and recognized jar aliases; ambiguous grouped pets are not guessed. */
    java.util.Set<String> availableItems()
    {
        java.util.Set<String> result = new java.util.LinkedHashSet<>();
        for (Map.Entry<String, Slots> entry : items.entrySet())
        {
            String name = entry.getKey(); Slots slots = entry.getValue();
            if (slots.approved < 0 || slots.approved >= 3 || name.startsWith("jar tier ") || name.startsWith("pet tier ")
                || name.length() > 100 || name.indexOf(';') >= 0 || name.chars().anyMatch(Character::isISOControl)) continue;
            result.add(name);
        }
        String[] jars = {"dreams", "spirits", "stone", "chemicals", "decay", "sand", "souls", "swamp", "venom",
            "dirt", "eyes", "feathers", "light", "miasma", "smoke"};
        for (String jar : jars)
        {
            String name = "jar of " + jar;
            Slots slots = lookup(name);
            if (slots != null && slots.approved < 3) result.add(name);
        }
        return result;
    }

    private static String normalize(String item) { return item.trim().replace('\u2019', '\'').toLowerCase(Locale.ROOT); }
    private static String attr(MutableAttributeSet set, String name)
    {
        for (Enumeration<?> keys = set.getAttributeNames(); keys.hasMoreElements();)
        {
            Object key = keys.nextElement();
            if (name.equalsIgnoreCase(key.toString())) return String.valueOf(set.getAttribute(key));
        }
        return null;
    }

    static final class Slots
    {
        final int approved, waiting;
        Slots(int approved, int waiting) { this.approved = approved; this.waiting = waiting; }
    }
}

package nl.dutchnations.server;

import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Team slots come from Instellingen; their display names come from the event. */
final class SheetTeamRoster
{
    static final String UNKNOWN = "Team onbekend";
    private final Map<String, Integer> slots;
    private final int teamCount;

    private SheetTeamRoster(Map<String, Integer> slots,int teamCount) { this.slots = Map.copyOf(slots);this.teamCount=teamCount; }

    static SheetTeamRoster parseCsv(String csv) throws IOException
    { return parseCsv(csv,2); }

    static SheetTeamRoster parseCsv(String csv,int teamCount) throws IOException
    {
        if(teamCount<2||teamCount>3)throw new IOException("Ongeldig aantal aparte teams");
        List<List<String>> rows = GoogleSheetDrops.csvRows(csv);
        // Only configured player columns A/E (and I for three teams), never payment details.
        int header = -1;
        for (int i = 0; i < Math.min(rows.size(), 4); i++)
        {
            List<String> row = rows.get(i);
            if (row.size() == teamCount && row.stream().allMatch(cell -> "speler (in-game)".equals(normalize(cell))))
            {
                if (header != -1) throw new IOException("Dubbele teamindeling-header");
                header = i;
            }
        }
        if (header < 0) throw new IOException("Teamindeling ontbreekt in Instellingen");
        Map<String, Integer> slots = new HashMap<>();
        for (int i = header + 1; i < rows.size(); i++)
        {
            List<String> row = rows.get(i);
            if (row.size() > teamCount) throw new IOException("Onverwachte teamindeling");
            for (int team = 0; team < row.size(); team++)
            {
                String player = normalize(row.get(team));
                if (player.isEmpty()) continue;
                // Duplicate in either column, including twice in one team: unknown.
                slots.merge(player, team + 1, (previous, next) -> 0);
            }
        }
        return new SheetTeamRoster(slots,teamCount);
    }

    String teamFor(String rsn, String eventTeamNames)
    {
        try
        {
            List<String> names = EventTeams.names(eventTeamNames);
            Integer slot = slots.get(normalize(rsn));
            return names.size() == teamCount && slot != null && slot > 0 ? names.get(slot - 1) : UNKNOWN;
        }
        catch (IllegalArgumentException ex) { return UNKNOWN; }
    }

    static String sourceId(String one, String two, String fallback)
    { return sourceId(one,two,null,fallback); }

    static String sourceId(String one, String two, String three, String fallback)
    {
        boolean separate = one != null && !one.trim().isEmpty() || two != null && !two.trim().isEmpty() || three != null && !three.trim().isEmpty();
        if (!separate) return GoogleSheetDrops.sheetId(fallback);
        String first = GoogleSheetDrops.sheetId(one), second = GoogleSheetDrops.sheetId(two);
        String third=three==null||three.trim().isEmpty()?first:GoogleSheetDrops.sheetId(three);
        return first != null && first.equals(second) && first.equals(third) ? first : null;
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.replace('\u00a0', ' ').replace('_', ' ').trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    interface Loader { SheetTeamRoster load(String sheetId,int teamCount) throws IOException; }

    /** Cache names/slots, not event display names; do not reuse stale data on failure. */
    static final class Lookup
    {
        private final Loader loader;
        private final Map<String, Cached> cache = new HashMap<>();
        Lookup(Loader loader) { this.loader = loader; }

        synchronized String teamFor(String sheetId, String rsn, String eventNames, long now)
        {
            int teamCount;
            try { teamCount=EventTeams.names(eventNames).size();if (sheetId == null || teamCount<2 || teamCount>3) return UNKNOWN; }
            catch (IllegalArgumentException ex) { return UNKNOWN; }
            cache.values().removeIf(value -> value.until <= now);
            String key=sheetId+"\n"+teamCount;
            Cached hit = cache.get(key);
            if (hit == null)
            {
                if (cache.size() >= 64) return UNKNOWN;
                try { hit = new Cached(loader.load(sheetId,teamCount), now + 30000); }
                catch (IOException | RuntimeException ex) { hit = new Cached(null, now + 5000); }
                cache.put(key, hit);
            }
            return hit.roster == null ? UNKNOWN : hit.roster.teamFor(rsn, eventNames);
        }
        private static final class Cached
        {
            final SheetTeamRoster roster;
            final long until;
            Cached(SheetTeamRoster roster, long until) { this.roster = roster; this.until = until; }
        }
    }
}

