    { BattleshipGame g = game(); g.fire(0, "H8", Set.of("DROP-1"), 500); rejects(() -> g.fire(0, "H8", all(), 500)); assertEquals(1, g.shots.get(0).size()); assertEquals(0, g.shots.get(1).size()); assertEquals(1, g.available(1, Set.of("DROP-1"))); }
