    static final class Google implements BattleshipGateway
    {
        Map<String,List<List<?>>> data=new HashMap<>();
        List<Map<String,List<List<?>>>> publicWrites=new ArrayList<>();
        Set<String> openOne=Set.of(),openTwo=Set.of();
        boolean failPublish;
