        Google()
        {
            data.put(MAIN+"Instellingen!B10:F12",List.of(List.of(46023.5,"","","",46023.6)));
            data.put(MAIN+"Instellingen!A17:G17",List.of(List.of("Rood","","","","Blauw")));
