    {
        Google google=new Google();google.data.put(MAIN+"Borddata!Z2",List.of(List.of("Bingo")));
        DutchNationsApi.Store store=new DutchNationsApi.Store(Files.createTempDirectory("battleship-idle-reset-").resolve("state.json"));
