            assertTrue(limits.remember("key"+i, 0));
        }
        assertFalse(limits.allow("overflow", 1, 1));
        assertFalse(limits.remember("overflow", 1));
        assertTrue(limits.allow("new", 1, 60000));
        assertTrue(limits.remember("new", 300000));
    }
