package nl.dutchnations.events;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

final class CodewordOverlay extends OverlayPanel
{
    private static final ZoneId DUTCH_TIME_ZONE = ZoneId.of("Europe/Amsterdam");
    private static final DateTimeFormatter DUTCH_TIME = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm z");
    private static final Color CODEWORD_COLOR = new Color(40, 255, 80);
    private final DutchNationsPlugin plugin;
    private final DutchNationsConfig config;

    @Inject
    CodewordOverlay(DutchNationsPlugin plugin, DutchNationsConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        OffsetDateTime currentMoment = OffsetDateTime.now();
        ClanFeed.ClanEvent event = plugin.activeEvent(currentMoment);
        if (!config.showOverlay() || event == null || event.codeword == null || event.codeword.trim().isEmpty()) return null;

        String timestamp = DUTCH_TIME.format(currentMoment.atZoneSameInstant(DUTCH_TIME_ZONE));
        int detailWidth = graphics.getFontMetrics().stringWidth(event.codeword + "  " + timestamp);
        int requiredWidth = Math.max(140, Math.min(250, detailWidth + 12));
        panelComponent.setPreferredSize(new Dimension(requiredWidth, 0));

        panelComponent.getChildren().add(LineComponent.builder()
            .left(event.codeword)
            .leftColor(CODEWORD_COLOR)
            .right(timestamp)
            .rightColor(Color.WHITE)
            .build());
        return super.render(graphics);
    }

}

package nl.dutchnations.events;

import java.time.OffsetDateTime;

/** Exact names and explicit name-fragment rules supplied by Sheet bingo tasks. */
final class DropMatcher
{
    private DropMatcher() { }

    static boolean matches(ClanFeed.ClanEvent event, String item, OffsetDateTime now)
    { return matches(event, event == null ? null : event.dropItems, item, now); }

    static boolean matches(ClanFeed.ClanEvent event, String selectedItems, String item, OffsetDateTime now)
    {
        if (event == null || selectedItems == null || item == null || item.trim().isEmpty()) return false;
        try
        {
            if (!event.active(now)) return false;
            for (String candidate : selectedItems.split(";"))
                if (matchesItem(candidate, item)) return true;
        }
        catch (RuntimeException ignored) { return false; }
        return false;
    }
    static String normalize(String name)
    { return name.trim().replace('’', '\'').toLowerCase(java.util.Locale.ROOT); }

    static boolean matchesItem(String rule, String item)
    {
        if (rule == null || item == null || item.trim().isEmpty()) return false;
        String selected = normalize(rule);
        String name = normalize(item);
        if (selected.startsWith("@namecontains:"))
        {
            String fragment = selected.substring("@namecontains:".length()).trim();
            return !fragment.isEmpty() && java.util.regex.Pattern.compile("(?<![\\p{L}\\p{N}])" + java.util.regex.Pattern.quote(fragment) + "(?![\\p{L}\\p{N}])")
                .matcher(name).find();
        }
        if (!selected.startsWith("@contains:")) return selected.equals(name);
        return java.util.regex.Pattern.compile("(?<![\\p{L}\\p{N}'])" + java.util.regex.Pattern.quote(name) + "(?![\\p{L}\\p{N}'])")
            .matcher(selected.substring("@contains:".length())).find();
    }
}

package nl.dutchnations.events;

import java.time.OffsetDateTime;

/** Screenshot participation does not grant or require a management role. */
final class DropScreenshotPolicy
{
    private DropScreenshotPolicy() { }

    static boolean allowed(boolean optedIn, boolean clanAccess, ClanFeed feed, String eventId, OffsetDateTime now)
    {
        if (!optedIn || !clanAccess || feed == null || feed.events == null || eventId == null) return false;
        for (ClanFeed.ClanEvent event : feed.events)
        {
            try { if (event != null && eventId.equals(event.id) && event.active(now)) return true; }
            catch (RuntimeException ignored) { /* Invalid or expired event data fails closed. */ }
        }
        return false;
    }
}

