        else if (("BOSS".equalsIgnoreCase(event.type) || "CLAN_EVENT".equalsIgnoreCase(event.type) || "CLAN_VS_CLAN".equalsIgnoreCase(event.type)) && !now.isBefore(event.start()) && !blank(event.driveUrl))
        {
