    private JPanel roleFilterBar()
    {
        JPanel filters = new JPanel(new java.awt.GridLayout(1, 3, 5, 5));
        filters.setOpaque(false); filters.setAlignmentX(Component.LEFT_ALIGNMENT);
        addRoleFilterButton(filters, "Admins", "ADMINS");
        addRoleFilterButton(filters, "Managers", "MANAGER");
        addRoleFilterButton(filters, "Teachers", "TEACHER");
        filters.setMaximumSize(new Dimension(Integer.MAX_VALUE, filters.getPreferredSize().height));
        return filters;
    }

    private void addRoleFilterButton(JPanel filters, String text, String filter)
    {
        JButton button = button(text);
        if (filter.equals(roleFilter)) button.setBackground(new Color(125, 93, 22));
        button.addActionListener(event -> { roleFilter = filter; render(); });
        filters.add(button);
    }

    private List<ManagementRole> filteredRoles()
    {
        return roles.stream()
            .filter(role -> matchesRoleFilter(role, roleFilter))
            .sorted(Comparator.comparingInt(this::roleOrder).thenComparing(role -> role.rsn, String.CASE_INSENSITIVE_ORDER))
            .collect(Collectors.toList());
    }

    private static boolean matchesRoleFilter(ManagementRole role, String filter)
    {
        if ("ALLE".equals(filter)) return true;
        if ("ADMINS".equals(filter)) return "OWNER".equalsIgnoreCase(role.role) || "ADMINISTRATOR".equalsIgnoreCase(role.role);
        if ("TEACHER".equals(filter)) return "TEACHER".equalsIgnoreCase(role.role) || "LEARNER_HOST".equalsIgnoreCase(role.role);
        return filter.equalsIgnoreCase(role.role);
    }

    private int roleOrder(ManagementRole role)
    {
        if ("OWNER".equalsIgnoreCase(role.role)) return 0;
        if ("ADMINISTRATOR".equalsIgnoreCase(role.role)) return 1;
        if ("MANAGER".equalsIgnoreCase(role.role)) return 2;
        return 3;
    }
    private static String roleLabel(String role)
    {
        return "LEARNER_HOST".equalsIgnoreCase(role) ? "TEACHER" : role;
    }
    private boolean canEdit(ClanFeed.ClanEvent event)
    {
        if (!canManage.getAsBoolean()) return false;
        if (!isLearnerHost.getAsBoolean()) return true;
        String rsn = currentRsn.get();
        return event.learner() && rsn != null && rsn.trim().equalsIgnoreCase(event.host == null ? "" : event.host.trim());
    }
    private static JButton button(String text)
    {
        JButton button = new JButton(text);
        button.setFocusable(false);
        button.setForeground(new Color(255, 231, 170));
        button.setBackground(RED);
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(176, 132, 48)), BorderFactory.createEmptyBorder(6, 10, 6, 10)));
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        return button;
    }
    private static JPanel card(Color color)
    {
        JPanel panel = new JPanel(); panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS)); panel.setBackground(color);
        panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10)); panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE)); return panel;
    }
    private static JLabel bodyLabel(String text, Color color, int style, float size)
    {
        JLabel label = new JLabel(text == null ? "" : text);
        label.setForeground(color);
        label.setFont(new Font(Font.SANS_SERIF, fontStyle(style), Math.round(size)));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }
    private static JTextArea bodyText(String text, Color color, int style, float size)
    {
        JTextArea area = new JTextArea(text == null ? "" : text);
        area.setLineWrap(true); area.setWrapStyleWord(true); area.setEditable(false); area.setFocusable(false);
        area.setOpaque(false); area.setForeground(color); area.setFont(new Font(Font.SANS_SERIF, fontStyle(style), Math.round(size)));
        area.setAlignmentX(Component.LEFT_ALIGNMENT);
        return area;
    }
    private static JLabel label(String text, Color color, int style, float size)
    {
        JLabel label = new JLabel(text == null ? "" : text); label.setForeground(color);
        label.setFont(label.getFont().deriveFont(style, size)); label.setAlignmentX(Component.LEFT_ALIGNMENT); return label;
    }
    private static int fontStyle(int style)
    {
        return style == Font.PLAIN || style == Font.BOLD || style == Font.ITALIC || style == (Font.BOLD | Font.ITALIC)
            ? style : Font.PLAIN;
    }
    private static boolean blank(String value) { return value == null || value.trim().isEmpty(); }
}

