                teamOneDropListUrl.getText(), teamTwoDropListUrl.getText(), teamThreeDropListUrl.getText());
            draft.registrationUrl = registrationUrl.getText().trim();
            draft.youtubeUrl = youtubeUrl.getText().trim();
            if (!draft.registrationUrl.isEmpty())
            {
                LocalDateTime registrationEnd = parseDateTime(registrationDeadlineDate.getText() + " " + registrationDeadlineTime.getText(), "aanmelddeadline");
                draft.registrationEndsAt = registrationEnd.atZone(ZoneId.systemDefault()).toOffsetDateTime().toString();
            }
            draft.checklist = checklist.getText().trim();
            draft.requiredPlugins = requiredPlugins.getText().trim();
            String selectedTemplate = (String) learnerTemplate.getSelectedItem();
            boolean hasLearnerTemplate = "LEARNER".equals(draft.type) && selectedTemplate != null && !"Geen sjabloon".equals(selectedTemplate);
            // Een learner-sjabloon bevat zijn eigen vaste Discord-beschrijving. Die moet
            // automatisch worden opgeslagen, zonder nogmaals een los invulvenster te tonen.
            draft.discordText = hasLearnerTemplate ? discordText.getText().trim() : "";
            draft.codewordRequired = "BOSS".equals(draft.type) || "CLAN_EVENT".equals(draft.type) || "CLAN_VS_CLAN".equals(draft.type) || ("MASS".equals(draft.type) && massCodewordRequired.isSelected());
            Object selectedStrategy = strategyWiki.getEditor().getItem();
            draft.strategyWikiUrl = selectedStrategy == null ? "" : strategyWikiUrl(selectedStrategy.toString(), templates);
            boolean boss = "BOSS".equals(draft.type);
            boolean mass = "MASS".equals(draft.type);
            boolean clanEvent = "CLAN_EVENT".equals(draft.type);
            boolean requiresCodeword = draft.codewordRequired;
            boolean learner = "LEARNER".equals(draft.type);
            boolean supportsResources = learner || mass;
            OffsetDateTime parsedStart = OffsetDateTime.parse(draft.startsAt);
            OffsetDateTime parsedEnd = OffsetDateTime.parse(draft.endsAt);
            if ((boss || clanEvent || clanVsClan) && !draft.registrationUrl.isEmpty() && OffsetDateTime.parse(draft.registrationEndsAt).isAfter(parsedStart))
                throw new IllegalArgumentException("De aanmelddeadline mag niet na de starttijd liggen.");
            if (draft.title.isEmpty()) throw new IllegalArgumentException(clanVsClan ? "Vul een activiteit in." : "Vul een titel in.");
            if (clanVsClan && (draft.clansOne.isEmpty() || draft.clansTwo.isEmpty())) throw new IllegalArgumentException("Vul beide clanlijsten in.");
            if (clanEvent && draft.bossList.isEmpty()) throw new IllegalArgumentException("Vul minimaal één boss of activiteit in.");
            if (!parsedEnd.isAfter(parsedStart)) throw new IllegalArgumentException("De einddatum en eindtijd moeten na de start liggen.");
            long durationHours = Duration.between(parsedStart, parsedEnd).toHours();
            if (!parsedStart.toLocalDate().equals(parsedEnd.toLocalDate()) || durationHours >= 12)
            {
                int confirm = JOptionPane.showConfirmDialog(null,
                    "Let op: dit event eindigt op " + parsedEnd.toLocalDate() + " om " + parsedEnd.toLocalTime() +
                        " en duurt ongeveer " + durationHours + " uur. Klopt dit?",
                    "Controleer de einddatum", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
                if (confirm != JOptionPane.YES_OPTION) continue;
            }
            if ((!boss && !clanVsClan) && draft.world.isEmpty())
            {
                JOptionPane.showMessageDialog(null, "Een learner-, mass- of clan-event heeft een wereld nodig.", "Controle", JOptionPane.WARNING_MESSAGE); continue;
            }
            if (draft.host.isEmpty())
            {
                markInvalid(host);
                JOptionPane.showMessageDialog(null, "Vul voor elk event een host in.", "Controle", JOptionPane.WARNING_MESSAGE); continue;
            }
            if (requiresCodeword && draft.codeword.isEmpty() && !editing)
            {
                markInvalid(codeword);
                JOptionPane.showMessageDialog(null, "Een boss-, mass- of clan-event heeft een codewoord nodig.", "Controle", JOptionPane.WARNING_MESSAGE); continue;
            }
            if (!requiresCodeword) draft.codeword = "";
            if (!learner) draft.checklist = "";
            if (!supportsResources) { draft.requiredPlugins = ""; draft.strategyWikiUrl = ""; }
            if (!clanVsClan) { draft.clansOne = ""; draft.clansTwo = ""; draft.activity = ""; }
            if (!clanEvent) draft.bossList = "";
            if (boss || clanVsClan) draft.world = "";
            if (!boss && !clanEvent && !clanVsClan && !mass) { draft.driveUrl = ""; draft.dropListUrl = ""; draft.registrationUrl = ""; draft.registrationEndsAt = ""; }
            if (!editing && !hasLearnerTemplate)
            {
                discordText.setLineWrap(true);
                discordText.setWrapStyleWord(true);
                int extraTextAnswer = JOptionPane.showConfirmDialog(null, discordText,
                    "Discord-beschrijving (optioneel)", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
                if (extraTextAnswer == JOptionPane.OK_OPTION) draft.discordText = discordText.getText().trim();
            }
            return draft;
        }
            catch (IllegalArgumentException e)
            {
                JOptionPane.showMessageDialog(null, e.getMessage(), "Ongeldige invoer", JOptionPane.ERROR_MESSAGE);
            }
        }
    }

    private static void markInvalid(JTextField field)
    {
        field.setBorder(BorderFactory.createLineBorder(new Color(215, 60, 60), 2));
        field.requestFocusInWindow();
    }

    static void validateTeamPages(EventDraft draft)
    {
        String one = value(draft.teamOneDropListUrl).trim(), two = value(draft.teamTwoDropListUrl).trim(), three = value(draft.teamThreeDropListUrl).trim();
        if (one.isEmpty() && two.isEmpty() && three.isEmpty()) return;
        if (!"CLAN_EVENT".equalsIgnoreCase(draft.type)) throw new IllegalArgumentException("Teamdroppagina's zijn alleen beschikbaar bij clan-events.");
        String names = validatedTeams(draft.type, draft.teamNames);
        int count = three.isEmpty() ? 2 : 3;
        if (names.isEmpty() || names.split(";").length != count) throw new IllegalArgumentException("Vul voor elk van de twee of drie teamnamen een eigen droppagina in. Laat Team 3 leeg bij twee teams.");
        java.util.Set<String> seen = new java.util.HashSet<>();
        String workbook = null;
        for (String page : count == 2 ? new String[]{one,two} : new String[]{one,two,three})
        {
            String key = GoogleSheetLink.tabKey(page);
            if (key == null) throw new IllegalArgumentException("Vul voor ieder team een Google Sheet-link naar het eigen tabblad in (met gid).");
            if (!seen.add(key)) throw new IllegalArgumentException("Gebruik voor ieder team een verschillende droppagina.");
            String id = key.substring(0,key.indexOf('/'));
            if (workbook != null && !workbook.equals(id)) throw new IllegalArgumentException("Gebruik teamtabbladen uit hetzelfde kijkbestand, zodat de teamindeling kan worden gevonden.");
            workbook = id;
        }
    }

    private static boolean usesMultipleTeams(String type, boolean selected)
    { return selected && "CLAN_EVENT".equals(type); }

    private static boolean hasTeamPages(String one, String two, String three)
    { return !value(one).trim().isEmpty() || !value(two).trim().isEmpty() || !value(three).trim().isEmpty(); }

    static void configureTeams(EventDraft draft, boolean selected, boolean legacyShared, String names, String one, String two, String three)
    {
        boolean useTeams = usesMultipleTeams(draft.type, selected);
        // Empty strings explicitly clear saved team settings; null would preserve them on edit.
        draft.teamNames = useTeams ? validatedTeams(draft.type, names) : "";
        draft.teamOneDropListUrl = useTeams ? value(one).trim() : "";
        draft.teamTwoDropListUrl = useTeams ? value(two).trim() : "";
        draft.teamThreeDropListUrl = useTeams ? value(three).trim() : "";
        if (!useTeams) return;
        if (draft.teamNames.isEmpty()) throw new IllegalArgumentException("Vul de teamnamen in of zet Meerdere teams uit.");
        if (!hasTeamPages(one, two, three) && !(legacyShared && GoogleSheetLink.supported(draft.dropListUrl)))
            throw new IllegalArgumentException("Vul bij Meerdere teams voor ieder team een eigen droppagina in.");
        validateTeamPages(draft);
    }

    static boolean showSharedDropList(String type, boolean useTeams, boolean legacyShared)
    {
        return ("BOSS".equals(type)||"MASS".equals(type)||"CLAN_VS_CLAN".equals(type))
            ||("CLAN_EVENT".equals(type)&&(!useTeams||legacyShared));
    }

    static String validatedTeams(String type, String value)
    {
        if (!"CLAN_EVENT".equals(type) || value == null || value.trim().isEmpty()) return "";
        if (value.length() > 300) throw new IllegalArgumentException("Teamnamen zijn te lang.");
        String[] parts = value.split(";", -1);
        if (parts.length < 2 || parts.length > 7) throw new IllegalArgumentException("Vul 2 tot en met 7 teams in, of laat teamnamen leeg.");
        java.util.Set<String> seen = new java.util.HashSet<>();
        java.util.List<String> names = new java.util.ArrayList<>();
        for (String part : parts)
        {
            String name = part.trim();
            if (name.isEmpty() || name.length() > 40 || name.chars().anyMatch(c -> Character.isISOControl(c) || c == '<' || c == '>'))
                throw new IllegalArgumentException("Gebruik teamnamen van 1 tot 40 tekens, gescheiden door ;");
            if (!seen.add(name.toLowerCase(java.util.Locale.ROOT))) throw new IllegalArgumentException("Teamnamen moeten uniek zijn.");
            names.add(name);
        }
        return String.join("; ", names);
    }
